import subprocess, struct
def get_matrix(dim,bucket,minn,maxn,seed=0):
 subprocess.run(["/workspace/executable","skipgram","-input","words.txt","-output","e0","-dim",str(dim),"-epoch","0","-thread","1","-minCount","1","-bucket",str(bucket),"-minn",str(minn),"-maxn",str(maxn),"-verbose","0","-seed",str(seed)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
 data=open("e0.bin","rb").read()
 off=64+28
 for i in range(13):
   while data[off]!=0: off+=1
   off+=1+9
 # prune etc? entries count may differ if bucket etc? dict size =13 still
 off+=1
 m,n=struct.unpack_from('<qq',data,off); off+=16
 vals=struct.unpack_from(f'<{m*n}f', data, off)
 return m,n,vals

def rngseq(seed,n,a):
 out=subprocess.check_output(["/tmp/rngseq",str(seed),str(n),str(a)]).decode().split()
 return [float(x) for x in out]

for dim,bucket,minn in [(5,100,3),(10,100,3),(100,100,3),(5,0,0),(10,0,0),(100,0,0),(20,100,3)]:
 m,n,vals=get_matrix(dim,bucket,minn,6 if minn else 0)
 seq=rngseq(0, len(vals), 1.0/dim)
 cnt=0
 for v,s in zip(vals,seq):
   if abs(v-s)>1e-9: break
   cnt+=1
 print(f"dim={dim} m={m} n={n} total={len(vals)} matched_consecutive={cnt}")
PY"}

