inline void Args::parseArgs(const std::vector<std::string>& argv, bool isQuantize) {
  for (size_t i = 0; i < argv.size(); i++) {
    const std::string& arg = argv[i];
    if (arg == "-h") {
      std::cerr << "Here is the help! Usage:\n\n";
      printUsage();
      exit(1);
    }
    auto need = [&]() -> std::string {
      if (i + 1 >= argv.size()) {
        std::cerr << arg << " is missing an argument\n\n";
        printUsage();
        exit(1);
      }
      return argv[++i];
    };
    if (arg.empty() || arg[0] != '-') {
      std::cerr << "Provided argument without a dash! Usage:\n\n";
      printUsage();
      exit(1);
    } else if (arg == "-input") {
      input = need();
    } else if (arg == "-output") {
      output = need();
    } else if (arg == "-verbose") {
      verbose = std::stoi(need());
    } else if (arg == "-minCount") {
      minCount = std::stoi(need());
    } else if (arg == "-minCountLabel") {
      minCountLabel = std::stoi(need());
    } else if (arg == "-wordNgrams") {
      wordNgrams = std::stoi(need()); manualWordNgrams = true;
    } else if (arg == "-bucket") {
      bucket = std::stoi(need());
    } else if (arg == "-minn") {
      minn = std::stoi(need()); manualMinn = true;
    } else if (arg == "-maxn") {
      maxn = std::stoi(need()); manualMaxn = true;
    } else if (arg == "-t") {
      t = std::stod(need());
    } else if (arg == "-label") {
      label = need();
    } else if (arg == "-lr") {
      lr = std::stod(need()); manualLr = true;
    } else if (arg == "-lrUpdateRate") {
      lrUpdateRate = std::stoi(need());
    } else if (arg == "-dim") {
      dim = std::stoi(need()); manualDim = true;
    } else if (arg == "-ws") {
      ws = std::stoi(need()); manualWs = true;
    } else if (arg == "-epoch") {
      epoch = std::stoi(need()); manualEpoch = true;
    } else if (arg == "-neg") {
      neg = std::stoi(need()); manualNeg = true;
    } else if (arg == "-loss") {
      std::string v = need(); manualLoss = true;
      if (v == "hs") loss = LossName::hs;
      else if (v == "ns") loss = LossName::ns;
      else if (v == "softmax") loss = LossName::softmax;
      else if (v == "one-vs-all" || v == "ova") loss = LossName::ova;
      else {
        std::cerr << "Unknown loss: " << v << "\n\n";
        printUsage();
        exit(1);
      }
    } else if (arg == "-thread") {
      thread = std::stoi(need());
    } else if (arg == "-pretrainedVectors") {
      pretrainedVectors = need();
    } else if (arg == "-saveOutput") {
      saveOutput = true;
    } else if (arg == "-seed") {
      seed = std::stoi(need());
    } else if (arg == "-autotune-validation") {
      autotuneValidation = need();
    } else if (arg == "-autotune-metric") {
      autotuneMetric = need();
    } else if (arg == "-autotune-predictions") {
      autotunePredictions = std::stoi(need());
    } else if (arg == "-autotune-duration") {
      autotuneDuration = std::stoi(need());
    } else if (arg == "-autotune-modelsize") {
      autotuneModelSize = need();
    } else if (arg == "-cutoff") {
      cutoff = std::stoi(need());
    } else if (arg == "-retrain") {
      retrain = true;
    } else if (arg == "-qnorm") {
      qnorm = true;
    } else if (arg == "-qout") {
      qout = true;
    } else if (arg == "-dsub") {
      dsub = std::stoi(need());
    } else {
      std::cerr << "Unknown argument: " << arg << "\n\n";
      printUsage();
      exit(1);
    }
  }
  if (input.empty() || output.empty()) {
    if (isQuantize) {
      std::cerr << "usage: fasttext quantize <args>\n\n";
    } else {
      std::cerr << "Empty input or output path.\n\n";
    }
    printUsage();
    exit(1);
  }
}

// ---------------------------------------------------------------- Vector / Matrix
struct Vector {
  std::vector<real> data_;
  Vector() {}
  explicit Vector(int64_t m) : data_((size_t)m) {}
  int64_t size() const { return (int64_t)data_.size(); }
  real& operator[](int64_t i) { return data_[(size_t)i]; }
  const real& operator[](int64_t i) const { return data_[(size_t)i]; }
  void zero() { std::fill(data_.begin(), data_.end(), 0); }
  void mul(real c) { for (auto& x : data_) x *= c; }
  void addVector(const Vector& v) { for (size_t i = 0; i < data_.size(); i++) data_[i] += v.data_[i]; }
  void addVector(const Vector& v, real c) { for (size_t i = 0; i < data_.size(); i++) data_[i] += c * v.data_[i]; }
  real dot(const Vector& v) const { real s = 0; for (size_t i = 0; i < data_.size(); i++) s += data_[i] * v.data_[i]; return s; }
  real norm() const { real s = 0; for (auto x : data_) s += x * x; return std::sqrt(s); }
  void normalize() {
    real n = norm();
    if (n > 0) { for (auto& x : data_) x /= n; }
  }
};

inline std::ostream& operator<<(std::ostream& os, const Vector& v) {
  // matches the observed 5-significant-digit vector printing
  std::ios::fmtflags oldFlags = os.flags();
  std::streamsize oldPrec = os.precision();
  os << std::setprecision(5);
  for (int64_t i = 0; i < v.size(); i++) os << v[i] << ' ';
  os.flags(oldFlags); os.precision(oldPrec);
  return os;
}

class Matrix {
 public:
  virtual ~Matrix() {}
  virtual int64_t size(int64_t i) const = 0; // 0 rows, 1 cols
  virtual void addRowToVector(Vector& vec, int64_t row) const = 0;
  virtual real dotRow(const Vector& vec, int64_t row) const = 0;
  virtual void addVectorToRow(const Vector& vec, int64_t row, real coeff) = 0;
  virtual void save(std::ostream& out) const = 0;
  virtual void load(std::istream& in) = 0;
  virtual bool isQuant() const { return false; }
  virtual real l2NormRow(int64_t row) const {
    Vector v(size(1)); v.zero(); addRowToVector(v, row); return v.norm();
  }
};

class DenseMatrix : public Matrix {
 public:
  class EncounteredNaNError : public std::exception {
   public:
    const char* what() const noexcept override { return "Encountered NaN."; }
  };
  int64_t m_ = 0, n_ = 0;
  std::vector<real> data_;
  DenseMatrix() {}
  DenseMatrix(int64_t m, int64_t n) : m_(m), n_(n), data_((size_t)(m * n), 0) {}
  int64_t size(int64_t i) const override { return i == 0 ? m_ : n_; }
  void zero() { std::fill(data_.begin(), data_.end(), 0); }
  void uniform(real a, int seed) {
    // Observed behaviour: only the first tenth of the entries (in
    // row-major order) are drawn from the generator; the rest remain
    // zero-initialised in this implementation.
    std::minstd_rand rng((unsigned int)seed);
    std::uniform_real_distribution<> uniform(-(double)a, (double)a);
    int64_t total = m_ * n_;
    int64_t count = total / 10;
    for (int64_t i = 0; i < count; i++) {
      data_[(size_t)i] = (real)uniform(rng);
    }
  }
  real& at(int64_t r, int64_t c) { return data_[(size_t)(r * n_ + c)]; }
  real at(int64_t r, int64_t c) const { return data_[(size_t)(r * n_ + c)]; }
  void addRowToVector(Vector& vec, int64_t row) const override {
    const real* p = &data_[(size_t)(row * n_)];
    for (int64_t i = 0; i < n_; i++) vec.data_[(size_t)i] += p[i];
  }
  real dotRow(const Vector& vec, int64_t row) const override {
    real s = 0;
    const real* p = &data_[(size_t)(row * n_)];
    for (int64_t i = 0; i < n_; i++) s += p[i] * vec.data_[(size_t)i];
    if (std::isnan((double)s)) throw EncounteredNaNError();
    return s;
  }
  void addVectorToRow(const Vector& vec, int64_t row, real coeff) override {
    real* p = &data_[(size_t)(row * n_)];
    for (int64_t i = 0; i < n_; i++) p[i] += coeff * vec.data_[(size_t)i];
  }
  void save(std::ostream& out) const override {
    out.write((const char*)&m_, sizeof(m_));
    out.write((const char*)&n_, sizeof(n_));
    out.write((const char*)data_.data(), (std::streamsize)(sizeof(real) * data_.size()));
  }
  void load(std::istream& in) override {
    in.read((char*)&m_, sizeof(m_));
    in.read((char*)&n_, sizeof(n_));
    data_.assign((size_t)(m_ * n_), 0);
    in.read((char*)data_.data(), (std::streamsize)(sizeof(real) * data_.size()));
  }
};

// ------------------------------------------------------- Product quantizer
struct ProductQuantizer {
  int32_t dim_ = 0;
  int32_t nsubq_ = 0;
  int32_t dsub_ = 0;
  int32_t lastd_ = 0;
  static const int32_t ksub_ = 256;
  std::vector<real> centroids; // dim * ksub, laid out subq * ksub * subdim
  ProductQuantizer() {}
  ProductQuantizer(int32_t dim, int32_t dsub) { init(dim, dsub); }
  void init(int32_t dim, int32_t dsub) {
    dim_ = dim; dsub_ = dsub;
    if (dsub <= 0) dsub_ = 1;
    nsubq_ = dim_ / dsub_;
    if (nsubq_ <= 0) nsubq_ = 1;
    // subquantizers: first nsubq-1 have dsub dims, last has remaining
    // To match the observed file layout when dim %% dsub == 0, keep as is.
    // Recompute in the style used below: number of subquantizers
    nsubq_ = (dim_ + dsub_ - 1) / dsub_;
    lastd_ = dim_ - (nsubq_ - 1) * dsub_;
    centroids.assign((size_t)dim_ * ksub_, 0);
  }
  int32_t subdim(int32_t sub) const { return sub == nsubq_ - 1 ? lastd_ : dsub_; }
  const real* getCentroid(int32_t sub, int32_t code) const {
    // centroids stored per subquantizer contiguously:
    // offset = sub * ksub * dsub .. but last segment smaller; compute offset
    int64_t off = 0;
    for (int32_t s = 0; s < sub; s++) off += (int64_t)ksub_ * subdim(s);
    return &centroids[(size_t)(off + (int64_t)code * subdim(sub))];
  }
  real* getCentroid(int32_t sub, int32_t code) {
    int64_t off = 0;
    for (int32_t s = 0; s < sub; s++) off += (int64_t)ksub_ * subdim(s);
    return &centroids[(size_t)(off + (int64_t)code * subdim(sub))];
  }
  void train(int n, const real* x, std::minstd_rand& rng);
  void computeCodes(const real* x, uint8_t* codes, int64_t count) const {
    for (int64_t i = 0; i < count; i++) {
      const real* v = x + i * dim_;
      uint8_t* c = codes + i * nsubq_;
      for (int32_t s = 0; s < nsubq_; s++) {
        int32_t sd = subdim(s);
        const real* subvec = v + s * dsub_;
        real best = std::numeric_limits<real>::max();
        int bestId = 0;
        for (int32_t k = 0; k < ksub_; k++) {
          const real* cen = getCentroid(s, k);
          real dist = 0;
          for (int32_t j = 0; j < sd; j++) { real d = subvec[j] - cen[j]; dist += d * d; }
          if (dist < best) { best = dist; bestId = k; }
        }
        c[s] = (uint8_t)bestId;
      }
    }
  }
  void reconstruct(const uint8_t* codes, real* out, int64_t count) const {
    for (int64_t i = 0; i < count; i++) {
      const uint8_t* c = codes + i * nsubq_;
      real* o = out + i * dim_;
      for (int32_t s = 0; s < nsubq_; s++) {
        int32_t sd = subdim(s);
        const real* cen = getCentroid(s, c[s]);
        for (int32_t j = 0; j < sd; j++) o[s * dsub_ + j] = cen[j];
      }
    }
  }
  void save(std::ostream& out) const {
    int32_t vals[4] = {dim_, nsubq_, dsub_, lastd_};
    // Observed: when dim%dsub==0 this is (dim,dim/dsub,dsub,dsub)
    out.write((const char*)vals, sizeof(vals));
    out.write((const char*)centroids.data(), (std::streamsize)(sizeof(real) * centroids.size()));
  }
  void load(std::istream& in) {
    int32_t vals[4] = {0, 0, 0, 0};
    in.read((char*)vals, sizeof(vals));
    dim_ = vals[0]; nsubq_ = vals[1]; dsub_ = vals[2]; lastd_ = vals[3];
    if (nsubq_ <= 0) { init(dim_, dsub_ > 0 ? dsub_ : 2); return; }
    centroids.assign((size_t)dim_ * ksub_, 0);
    in.read((char*)centroids.data(), (std::streamsize)(sizeof(real) * centroids.size()));
  }
};

class QuantMatrix : public Matrix {
 public:
  bool qnorm_ = false;
  int64_t m_ = 0, n_ = 0;
  ProductQuantizer pq_;
  ProductQuantizer npq_; // for norms, only if qnorm
  std::vector<uint8_t> codes_;
  std::vector<uint8_t> normCodes_;
  QuantMatrix() {}
  int64_t size(int64_t i) const override { return i == 0 ? m_ : n_; }
  bool isQuant() const override { return true; }
  void buildFromDense(const DenseMatrix& dense, int32_t dsub, bool qnorm, std::minstd_rand& rng);
  void addRowToVector(Vector& vec, int64_t row) const override {
    // reconstruct row
    const uint8_t* code = &codes_[(size_t)(row * pq_.nsubq_)];
    real normMult = 1;
    if (qnorm_) {
      real nr[1] = {0};
      // norm code is a 1-dim pq
      {
        const uint8_t* nc = &normCodes_[(size_t)row];
        const real* cen = npq_.getCentroid(0, nc[0]);
        normMult = cen[0];
      }
      (void)nr;
    }
    for (int32_t s = 0; s < pq_.nsubq_; s++) {
      int32_t sd = pq_.subdim(s);
      const real* cen = pq_.getCentroid(s, code[s]);
      for (int32_t j = 0; j < sd; j++) vec.data_[(size_t)(s * pq_.dsub_ + j)] += normMult * cen[j];
    }
  }
  real dotRow(const Vector& vec, int64_t row) const override {
    Vector tmp(vec.size()); tmp.zero(); addRowToVector(tmp, row);
    real s = tmp.dot(vec);
    if (std::isnan((double)s)) throw DenseMatrix::EncounteredNaNError();
    return s;
  }
  void addVectorToRow(const Vector&, int64_t, real) override {
    throw std::invalid_argument("QuantMatrix cannot be updated");
  }
  void save(std::ostream& out) const override {
    out.write((const char*)&qnorm_, sizeof(qnorm_));
    out.write((const char*)&m_, sizeof(m_));
    out.write((const char*)&n_, sizeof(n_));
    int32_t codesSize = (int32_t)codes_.size();
    out.write((const char*)&codesSize, sizeof(codesSize));
    out.write((const char*)codes_.data(), (std::streamsize)codes_.size());
    pq_.save(out);
    if (qnorm_) {
      int32_t ncSize = (int32_t)normCodes_.size();
      out.write((const char*)&ncSize, sizeof(ncSize));
      out.write((const char*)normCodes_.data(), (std::streamsize)normCodes_.size());
      npq_.save(out);
    }
  }
  void load(std::istream& in) override {
    in.read((char*)&qnorm_, sizeof(qnorm_));
    in.read((char*)&m_, sizeof(m_));
    in.read((char*)&n_, sizeof(n_));
    int32_t codesSize = 0;
    in.read((char*)&codesSize, sizeof(codesSize));
    codes_.assign((size_t)(codesSize > 0 ? codesSize : 0), 0);
    in.read((char*)codes_.data(), (std::streamsize)codes_.size());
    pq_.load(in);
    if (qnorm_) {
      int32_t ncSize = 0;
      in.read((char*)&ncSize, sizeof(ncSize));
      normCodes_.assign((size_t)(ncSize > 0 ? ncSize : 0), 0);
      in.read((char*)normCodes_.data(), (std::streamsize)normCodes_.size());
      npq_.load(in);
    }
  }
};

inline void ProductQuantizer::train(int n, const real* x, std::minstd_rand& rng) {
  if (n <= 0) return;
  const int np = std::min(n, 30000);
  // For each subquantizer run a small Lloyd iteration.
  std::vector<int> perm((size_t)n);
  std::iota(perm.begin(), perm.end(), 0);
  for (int32_t s = 0; s < nsubq_; s++) {
    int32_t sd = subdim(s);
    // initialise centroids with distinct sampled points (sub-vectors)
    std::vector<int> sampleIdx = perm;
    // partial shuffle deterministically from the shared rng
    for (int32_t i = 0; i < ksub_ && i < (int32_t)sampleIdx.size(); i++) {
      int32_t j = i + (sampleIdx.size() - i > 0 ? (int32_t)(rng() % (uint32_t)std::max<int64_t>(1, (int64_t)sampleIdx.size() - i)) : 0);
      std::swap(sampleIdx[(size_t)i], sampleIdx[(size_t)j]);
    }
    for (int32_t k = 0; k < ksub_; k++) {
      real* cen = getCentroid(s, k);
      int idx = sampleIdx[(size_t)(k % (int32_t)sampleIdx.size())];
      const real* src = x + (int64_t)idx * dim_ + s * dsub_;
      for (int32_t j = 0; j < sd; j++) cen[j] = src[j];
    }
    // choose training subset indices (first np after a shuffle)
    std::vector<int> trainIdx((size_t)n);
    std::iota(trainIdx.begin(), trainIdx.end(), 0);
    for (int32_t i = 0; i < np; i++) {
      int32_t j = i + (int32_t)(rng() % (uint32_t)std::max<int>(1, n - i));
      if (j < n) std::swap(trainIdx[(size_t)i], trainIdx[(size_t)j]);
    }
    std::vector<int> assign((size_t)np);
    std::vector<real> sums((size_t)ksub_ * sd);
    std::vector<int> counts((size_t)ksub_);
    for (int iter = 0; iter < 25; iter++) {
      std::fill(sums.begin(), sums.end(), 0);
      std::fill(counts.begin(), counts.end(), 0);
      for (int i = 0; i < np; i++) {
        const real* subvec = x + (int64_t)trainIdx[(size_t)i] * dim_ + s * dsub_;
        real best = std::numeric_limits<real>::max(); int bestId = 0;
        for (int32_t k = 0; k < ksub_; k++) {
          const real* cen = getCentroid(s, k);
          real dist = 0; for (int32_t j = 0; j < sd; j++) { real d = subvec[j] - cen[j]; dist += d * d; }
          if (dist < best) { best = dist; bestId = k; }
        }
        assign[(size_t)i] = bestId;
        counts[(size_t)bestId]++;
        for (int32_t j = 0; j < sd; j++) sums[(size_t)bestId * sd + j] += subvec[j];
      }
      for (int32_t k = 0; k < ksub_; k++) {
        real* cen = getCentroid(s, k);
        if (counts[(size_t)k] > 0) {
          for (int32_t j = 0; j < sd; j++) cen[j] = sums[(size_t)k * sd + j] / counts[(size_t)k];
        }
      }
    }
  }
}

inline void QuantMatrix::buildFromDense(const DenseMatrix& dense, int32_t dsub, bool qnorm, std::minstd_rand& rng) {
  m_ = dense.m_; n_ = dense.n_; qnorm_ = qnorm;
  if (m_ < 256) {
    throw std::invalid_argument("Matrix too small for quantization, must have at least 256 rows");
  }
  pq_.init((int32_t)n_, dsub);
  std::vector<real> work = dense.data_;
  std::vector<real> norms;
  if (qnorm_) {
    norms.assign((size_t)m_, 0);
    for (int64_t i = 0; i < m_; i++) {
      real s = 0; for (int64_t j = 0; j < n_; j++) { real v = work[(size_t)(i * n_ + j)]; s += v * v; }
      s = std::sqrt(s); norms[(size_t)i] = s;
      if (s > 0) for (int64_t j = 0; j < n_; j++) work[(size_t)(i * n_ + j)] /= s;
    }
    npq_.init(1, 1);
    npq_.train((int)m_, norms.data(), rng);
    normCodes_.assign((size_t)m_, 0);
    npq_.computeCodes(norms.data(), normCodes_.data(), m_);
  }
  pq_.train((int)m_, work.data(), rng);
  codes_.assign((size_t)(m_ * pq_.nsubq_), 0);
  pq_.computeCodes(work.data(), codes_.data(), m_);
}

// ------------------------------------------------------------- Reader
struct LineReader {
  std::istream* in = nullptr;
  bool pendingEos = false;
  int64_t consumed = 0;
  explicit LineReader(std::istream* s) : in(s) {}
  bool readWord(std::string& token) {
    token.clear();
    if (pendingEos) { pendingEos = false; token = EOS; return true; }
    if (!in) return false;
    std::streambuf* sb = in->rdbuf();
    int ci;
    while ((ci = sb->sbumpc()) != std::streambuf::traits_type::eof()) {
      consumed++;
      char c = (char)ci;
      if (c == ' ' || c == '\n' || c == '\t' || c == '\v' || c == '\f' || c == '\r' || c == '\0') {
        if (token.empty()) {
          if (c == '\n') { token = EOS; return true; }
          continue;
        } else {
          if (c == '\n') pendingEos = true;
          return true;
        }
      } else {
        token.push_back(c);
      }
    }
    return !token.empty();
  }
};

// ------------------------------------------------------------- Dictionary
enum class EntryType : int8_t { word = 0, label = 1 };
struct Entry {
  std::string word;
  int64_t count = 0;
  EntryType type = EntryType::word;
  std::vector<int32_t> subwords;
};

class Dictionary {
 public:
  std::shared_ptr<Args> args_;
  int32_t size_ = 0;
  int32_t nwords_ = 0;
  int32_t nlabels_ = 0;
  int64_t ntokens_ = 0;
  int64_t pruneidx_size_ = -1;
  std::vector<Entry> words_;
  std::unordered_map<std::string, int32_t> word2int_;
  std::vector<real> pdiscard_;
  std::unordered_map<int32_t, int32_t> pruneidx_; // old ngram id -> new id
  static const int32_t MAX_NGRAM_ID = 0; // unused marker
  explicit Dictionary(std::shared_ptr<Args> args) : args_(args) {}

  static uint32_t hash(const std::string& str) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < str.size(); i++) {
      h = h ^ (uint32_t)(uint8_t)str[i];
      h = h * 16777619u;
    }
    return h;
  }
  EntryType getEntryType(const std::string& w) const {
    return startsWith(w, args_->label) ? EntryType::label : EntryType::word;
  }
  EntryType getEntryType(int32_t i) const { return words_[(size_t)i].type; }
  int32_t getId(const std::string& w) const {
    auto it = word2int_.find(w);
    return it == word2int_.end() ? -1 : it->second;
  }
  const std::string& getWord(int32_t i) const { return words_[(size_t)i].word; }
  const std::string& getLabel(int32_t i) const { return words_[(size_t)(nwords_ + i)].word; }
  int32_t nwords() const { return nwords_; }
  int32_t nlabels() const { return nlabels_; }
  int32_t size() const { return size_; }

  void add(const std::string& w) {
    auto it = word2int_.find(w);
    if (it == word2int_.end()) {
      Entry e; e.word = w; e.count = 1; e.type = getEntryType(w);
      words_.push_back(e);
      word2int_[w] = (int32_t)words_.size() - 1;
    } else {
      words_[(size_t)it->second].count++;
    }
  }
  void rebuildIndex() {
    word2int_.clear();
    for (int32_t i = 0; i < (int32_t)words_.size(); i++) word2int_[words_[(size_t)i].word] = i;
    size_ = (int32_t)words_.size();
    nwords_ = 0; nlabels_ = 0;
    for (auto& e : words_) { if (e.type == EntryType::word) nwords_++; else nlabels_++; }
  }
  void sortEntries() {
    std::sort(words_.begin(), words_.end(), [](const Entry& a, const Entry& b) {
      if (a.type != b.type) return (int)a.type < (int)b.type;
      return a.count > b.count;
    });
    rebuildIndex();
  }
  void threshold(int64_t minCount, int64_t minCountLabel) {
    std::vector<Entry> keep;
    keep.reserve(words_.size());
    for (auto& e : words_) {
      if ((e.type == EntryType::word && e.count >= minCount) ||
          (e.type == EntryType::label && e.count >= minCountLabel)) keep.push_back(e);
    }
    words_ = keep;
    sortEntries();
  }
  void computeDiscard() {
    pdiscard_.assign((size_t)size_, 0);
    if (ntokens_ == 0) return;
    for (int32_t i = 0; i < size_; i++) {
      real f = (real)((double)words_[(size_t)i].count / (double)ntokens_);
      double tf = f == 0 ? 0 : args_->t / (double)f;
      pdiscard_[(size_t)i] = (real)(std::sqrt(tf) + tf);
    }
  }
  // character ngrams
  void computeSubwords(const std::string& word, std::vector<int32_t>& ngrams,
                       std::vector<std::string>* substrings = nullptr) const {
    // split into unicode characters (byte groups)
    struct CharSpan { size_t start; size_t len; };
    std::vector<CharSpan> chars;
    for (size_t i = 0; i < word.size();) {
      size_t start = i;
      i++;
      while (i < word.size() && ((uint8_t)word[i] & 0xC0) == 0x80) i++;
      chars.push_back({start, i - start});
    }
    for (size_t ci = 0; ci < chars.size(); ci++) {
      std::string ngram;
      for (size_t cj = ci, n = 1; cj < chars.size() && n <= (size_t)std::max(0, args_->maxn); cj++, n++) {
        ngram.append(word.substr(chars[cj].start, chars[cj].len));
        if (n >= (size_t)std::max(0, args_->minn) && !(n == 1 && (ci == 0 || cj == chars.size() - 1))) {
          uint32_t h = hash(ngram);
          int32_t bucket = args_->bucket;
          int32_t id = nwords_ + (int32_t)(h % (uint32_t)bucket); // SIGFPE if bucket==0, mirroring the original
          if (pruneidx_size_ >= 0) {
            auto it = pruneidx_.find(id);
            if (it == pruneidx_.end()) continue;
            id = it->second;
          }
          ngrams.push_back(id);
          if (substrings) substrings->push_back(ngram);
        }
      }
    }
  }
  void initSubwords() {
    for (int32_t i = 0; i < size_; i++) {
      auto& e = words_[(size_t)i];
      e.subwords.clear();
      e.subwords.push_back(i);
      if (e.word != EOS) {
        std::string wrapped = std::string(BOW) + e.word + EOW;
        // compute but the first element (self) is retained; computeSubwords
        // appends only character ngram ids.
        computeSubwords(wrapped, e.subwords, nullptr);
      }
    }
  }
  void init() {
    computeDiscard();
    initSubwords();
  }
  std::vector<int32_t> getSubwords(int32_t id) const {
    return words_[(size_t)id].subwords;
  }
  std::vector<int32_t> getSubwords(const std::string& word) const {
    int32_t id = getId(word);
    if (id >= 0) return getSubwords(id);
    std::vector<int32_t> res;
    if (word != EOS) computeSubwords(std::string(BOW) + word + EOW, res, nullptr);
    return res;
  }
  void getSubwords(const std::string& word, std::vector<int32_t>& ngrams,
                   std::vector<std::string>& substrings) const {
    int32_t id = getId(word);
    ngrams.clear(); substrings.clear();
    if (id >= 0) {
      ngrams = getSubwords(id);
      substrings.reserve(ngrams.size());
      if (!ngrams.empty()) {
        substrings.push_back(word);
        // regenerate substrings for character ngrams
        if (word != EOS) {
          std::vector<int32_t> tmp;
          std::vector<std::string> subs;
          computeSubwords(std::string(BOW) + word + EOW, tmp, &subs);
          // tmp aligns with the character part of ngrams; if pruning altered
          // counts, fall back to aligning by order as best as possible.
          for (auto& s : subs) substrings.push_back(s);
        }
      }
      // If counts diverge (pruned), trim / extend defensively to match ngrams
      if (substrings.size() > ngrams.size()) substrings.resize(ngrams.size());
      while (substrings.size() < ngrams.size()) substrings.push_back(word);
    } else {
      if (word != EOS) computeSubwords(std::string(BOW) + word + EOW, ngrams, &substrings);
    }
  }
  void addSubwords(std::vector<int32_t>& line, const std::string& token, int32_t wid) const {
    if (wid < 0) {
      if (token != EOS) computeSubwords(std::string(BOW) + token + EOW, line, nullptr);
    } else {
      if (args_->maxn <= 0) {
        line.push_back(wid);
      } else {
        const auto& sw = words_[(size_t)wid].subwords;
        line.insert(line.end(), sw.begin(), sw.end());
      }
    }
  }
  void addWordNgrams(std::vector<int32_t>& line, const std::vector<int32_t>& hashes, int32_t n) const {
    if (n <= 1) return;
    for (size_t i = 0; i < hashes.size(); i++) {
      uint64_t h = (uint64_t)(int64_t)hashes[i];
      for (size_t j = i + 1; j < hashes.size() && j < i + (size_t)n; j++) {
        h = h * 116049371ULL + (uint64_t)(int64_t)hashes[j];
        int32_t id = nwords_ + (int32_t)(h % (uint64_t)(uint32_t)args_->bucket);
        if (pruneidx_size_ >= 0) {
          auto it = pruneidx_.find(id);
          if (it == pruneidx_.end()) continue;
          id = it->second;
        }
        line.push_back(id);
      }
    }
  }
  // supervised / inference line
  int32_t getLine(LineReader& reader, std::vector<int32_t>& words, std::vector<int32_t>& labels) const {
    std::string token;
    std::vector<int32_t> wordHashes;
    words.clear(); labels.clear();
    while (reader.readWord(token)) {
      uint32_t h = hash(token);
      int32_t wid = getId(token);
      EntryType type = (wid < 0) ? getEntryType(token) : getEntryType(wid);
      if (type == EntryType::word) {
        addSubwords(words, token, wid);
        wordHashes.push_back((int32_t)h);
      } else if (type == EntryType::label && wid >= 0) {
        labels.push_back(wid - nwords_);
      }
      if (token == EOS) break;
    }
    addWordNgrams(words, wordHashes, args_->wordNgrams);
    return (int32_t)words.size();
  }
  // unsupervised training line (with discard)
  bool discardWord(int32_t id, std::minstd_rand& rng) const {
    // returns true if the word should be discarded
    std::uniform_real_distribution<> uniform(0, 1);
    return uniform(rng) > (double)pdiscard_[(size_t)id];
  }
  int32_t getLine(LineReader& reader, std::vector<int32_t>& words, std::minstd_rand& rng) const {
    std::string token;
    words.clear();
    while (reader.readWord(token)) {
      int32_t wid = getId(token);
      if (wid < 0) continue;
      EntryType type = getEntryType(wid);
      if (type == EntryType::word) {
        if (!discardWord(wid, rng)) words.push_back(wid);
        if (token == EOS) break;
      }
    }
    return (int32_t)words.size();
  }
  std::vector<int64_t> getCounts(EntryType type) const {
    std::vector<int64_t> res;
    for (auto& e : words_) if (e.type == type) res.push_back(e.count);
    return res;
  }
  void readFromInput(LineReader& reader) {
    std::string token;
    ntokens_ = 0;
    while (reader.readWord(token)) {
      add(token);
      ntokens_++;
      if (ntokens_ % 1000000 == 0 && args_->verbose > 1) {
        std::cerr << "\rRead " << (ntokens_ / 1000000) << "M words" << std::flush;
      }
    }
  }
  void save(std::ostream& out) const {
    auto wi32 = [&](int32_t x) { out.write((const char*)&x, sizeof(x)); };
    auto wi64 = [&](int64_t x) { out.write((const char*)&x, sizeof(x)); };
    wi32(size_); wi32(nwords_); wi32(nlabels_);
    wi64(ntokens_); wi64(pruneidx_size_);
    for (auto& e : words_) {
      out.write(e.word.c_str(), (std::streamsize)e.word.size() + 1);
      wi64(e.count);
      int8_t t = (int8_t)e.type;
      out.write((const char*)&t, sizeof(t));
    }
    for (auto& kv : pruneidx_) {
      // stored in map order in the original (std::map-like ordering by key);
      // pruneidx_ here is unordered, so this ordering is unspecified, but
      // load reconstructs the same mapping regardless of order.
    }
    if (pruneidx_size_ >= 0) {
      // write sorted by key for determinism
      std::vector<std::pair<int32_t,int32_t>> v(pruneidx_.begin(), pruneidx_.end());
      std::sort(v.begin(), v.end());
      for (auto& kv : v) { wi32(kv.first); wi32(kv.second); }
    }
  }
  void load(std::istream& in) {
    auto ri32 = [&]() -> int32_t { int32_t x = 0; in.read((char*)&x, sizeof(x)); return x; };
    auto ri64 = [&]() -> int64_t { int64_t x = 0; in.read((char*)&x, sizeof(x)); return x; };
    size_ = ri32(); nwords_ = ri32(); nlabels_ = ri32();
    ntokens_ = ri64(); pruneidx_size_ = ri64();
    words_.clear();
    for (int32_t i = 0; i < size_; i++) {
      Entry e;
      char c;
      while (in.get(c) && c != '\0') e.word.push_back(c);
      e.count = ri64();
      int8_t t = 0; in.read((char*)&t, sizeof(t)); e.type = (EntryType)t;
      words_.push_back(e);
    }
    pruneidx_.clear();
    for (int64_t i = 0; i < pruneidx_size_; i++) {
      int32_t a = ri32(); int32_t b = ri32(); pruneidx_[a] = b;
    }
    rebuildIndex();
    // sizes are as stored (rebuild recomputes the same values)
    size_ = (int32_t)words_.size();
  }
};

// ------------------------------------------------------------- Losses
struct ModelState {
  Vector hidden;
  Vector grad;
  Vector output;
  std::minstd_rand rng;
  double loss = 0;
  int64_t nexamples = 0;
  ModelState(int dim, int osz, int seed) : hidden(dim), grad(dim), output(osz), rng((unsigned int)seed) {
    hidden.zero(); grad.zero(); output.zero();
  }
};

class Loss {
 public:
  virtual ~Loss() {}
  virtual double update(const std::vector<int32_t>& input, int32_t target, real lr,
                        const std::shared_ptr<Matrix>& inputMat,
                        const std::shared_ptr<Matrix>& outputMat, ModelState& state,
                        const std::vector<int32_t>& allTargets) = 0;
  virtual void computeOutput(const Vector& hidden, Vector& out, const std::shared_ptr<Matrix>& outputMat) const = 0;
  // fill predictions (label id, probability), sorted descending by prob
  virtual void predict(const Vector& hidden, int32_t k, real threshold,
                       std::vector<std::pair<real,int32_t>>& predictions,
                       const std::shared_ptr<Matrix>& outputMat) const = 0;
  static double sigmoid(double x) {
    if (x > 10) return 1.0; // matches clamping behaviour widely used; refined below if needed
    if (x < -10) return 0.0;
    return 1.0 / (1.0 + std::exp(-x));
  }
  static double logSigmoid(double x) {
    if (x > 10) return 0.0;
    if (x < -10) return x;
    return -std::log(1.0 + std::exp(-x));
  }
};

static void collectTopK(const std::vector<std::pair<real,int32_t>>& scored, int32_t k, real threshold,
                        std::vector<std::pair<real,int32_t>>& predictions) {
  // scored: all (prob,id). Use a bounded heap mirroring a top-k selection,
  // then output in descending order. Ties keep the earlier behaviour of a
  // stable sort (dictionary order) as a reasonable deterministic choice.
  std::vector<std::pair<real,int32_t>> filtered;
  for (auto& p : scored) if (p.first > threshold) filtered.push_back(p);
  std::stable_sort(filtered.begin(), filtered.end(), [](const auto& a, const auto& b){ return a.first > b.first; });
  int64_t take;
  if (k < 0) take = (int64_t)filtered.size();
  else take = std::min<int64_t>(k, (int64_t)filtered.size());
  for (int64_t i = 0; i < take; i++) predictions.push_back(filtered[(size_t)i]);
}

class SoftmaxLoss : public Loss {
  int32_t osz_;
 public:
  explicit SoftmaxLoss(int32_t osz) : osz_(osz) {}
  void computeOutput(const Vector& hidden, Vector& out, const std::shared_ptr<Matrix>& outputMat) const override {
    out.zero();
    for (int32_t i = 0; i < osz_; i++) out[(size_t)i] = outputMat->dotRow(hidden, i);
    // softmax in place
    real mx = -std::numeric_limits<real>::max();
    for (int32_t i = 0; i < osz_; i++) mx = std::max(mx, out[(size_t)i]);
    double sum = 0;
    for (int32_t i = 0; i < osz_; i++) { out[(size_t)i] = (real)std::exp((double)out[(size_t)i] - mx); sum += out[(size_t)i]; }
    if (sum > 0) for (int32_t i = 0; i < osz_; i++) out[(size_t)i] = (real)(out[(size_t)i] / sum);
  }
  double update(const std::vector<int32_t>&, int32_t target, real lr,
                const std::shared_ptr<Matrix>& inputMat,
                const std::shared_ptr<Matrix>& outputMat, ModelState& state,
                const std::vector<int32_t>&) override {
    // state.hidden already set
    computeOutput(state.hidden, state.output, outputMat);
    state.grad.zero();
    for (int32_t i = 0; i < osz_; i++) {
      real prob = state.output[(size_t)i];
      real alpha = lr * ((i == target ? 1.0f : 0.0f) - prob);
      state.grad.addVector(state.hidden, 0); // placeholder no-op to keep shape clear
      // grad += alpha * outputRow(i)   (using row before its update)
      // implement via a temporary row vector
      {
        Vector row(state.hidden.size()); row.zero(); outputMat->addRowToVector(row, i);
        state.grad.addVector(row, alpha);
      }
      outputMat->addVectorToRow(state.hidden, i, alpha);
    }
    double loss = target >= 0 && target < osz_ ? -std::log((double)std::max<real>(state.output[(size_t)target], 1e-12f)) : 0;
    // update inputs
    if (!input.empty()) {}
    return loss;
  }
  void predict(const Vector& hidden, int32_t k, real threshold,
               std::vector<std::pair<real,int32_t>>& predictions,
               const std::shared_ptr<Matrix>& outputMat) const override {
    if (k == 0) throw std::invalid_argument("k needs to be 1 or higher!");
    Vector out(osz_); computeOutput(hidden, out, outputMat);
    std::vector<std::pair<real,int32_t>> scored;
    for (int32_t i = 0; i < osz_; i++) scored.push_back({out[(size_t)i], i});
    collectTopK(scored, k, threshold, predictions);
  }
};

// helper used by binary losses to finish input update
static void finishInputUpdate(const std::vector<int32_t>& input, const std::shared_ptr<Matrix>& inputMat, ModelState& state) {
  if (input.empty()) return;
  real coeff = 1.0f / (real)input.size();
  // state.grad already holds sum of alpha*outputRow (alpha includes lr)
  // input rows move by grad * (1/|input|) ; note sign: grad accumulated as
  // alpha*row with alpha = lr*(label - sigmoid), which is the ascent
  // direction for log-likelihood, matching the output update.
  for (auto id : input) inputMat->addVectorToRow(state.grad, id, coeff);
}

class BinaryLossBase : public Loss {
 protected:
  int32_t osz_;
  // one binary logistic step; returns log-likelihood term (negative loss)
  double binaryLogistic(int32_t targetIdx, bool isTarget, real lr,
                        const std::shared_ptr<Matrix>& outputMat, ModelState& state) const {
    real score = outputMat->dotRow(state.hidden, targetIdx);
    double sig = sigmoid(score);
    real alpha = (real)(lr * ((isTarget ? 1.0 : 0.0) - sig));
    // grad += alpha * outputRow
    {
      Vector row(state.hidden.size()); row.zero(); outputMat->addRowToVector(row, targetIdx);
      state.grad.addVector(row, alpha);
    }
    outputMat->addVectorToRow(state.hidden, targetIdx, alpha);
    return isTarget ? logSigmoid(score) : logSigmoid(-score);
  }
 public:
  explicit BinaryLossBase(int32_t osz) : osz_(osz) {}
};

class NegativeSamplingLoss : public BinaryLossBase {
  int32_t neg_;
  std::vector<int32_t> table_;
  std::vector<int64_t> counts_;
  static const int32_t NEG_TABLE_SIZE = 10000000;
 public:
  NegativeSamplingLoss(int32_t osz, int32_t neg, const std::vector<int64_t>& counts)
      : BinaryLossBase(osz), neg_(neg), counts_(counts) { buildTable(); }
  void buildTable() {
    if (osz_ <= 0) return;
    double z = 0;
    for (auto c : counts_) z += std::pow((double)c, 0.5);
    if (z == 0) return;
    table_.assign(NEG_TABLE_SIZE, 0);
    int32_t idx = 0;
    double cur = std::pow((double)counts_[0], 0.5) / z;
    for (int32_t i = 0; i < NEG_TABLE_SIZE; i++) {
      table_[(size_t)i] = idx;
      if ((double)i / NEG_TABLE_SIZE > cur) {
        idx++;
        if (idx >= osz_) idx = osz_ - 1;
        else cur += std::pow((double)counts_[(size_t)idx], 0.5) / z;
      }
    }
  }
  int32_t getNeg(int32_t target, std::minstd_rand& rng) const {
    if (table_.empty()) return 0;
    int32_t neg;
    do {
      neg = table_[rng() % (uint32_t)table_.size()];
    } while (neg == target);
    return neg;
  }
  void computeOutput(const Vector& hidden, Vector& out, const std::shared_ptr<Matrix>& outputMat) const override {
    out.zero();
    for (int32_t i = 0; i < osz_; i++) out[(size_t)i] = (real)sigmoid(outputMat->dotRow(hidden, i));
  }
  double update(const std::vector<int32_t>& input, int32_t target, real lr,
                const std::shared_ptr<Matrix>& inputMat,
                const std::shared_ptr<Matrix>& outputMat, ModelState& state,
                const std::vector<int32_t>&) override {
    state.grad.zero();
    double loss = 0;
    loss -= binaryLogistic(target, true, lr, outputMat, state);
    for (int32_t i = 0; i < neg_; i++) {
      int32_t negt = getNeg(target, state.rng);
      loss -= binaryLogistic(negt, false, lr, outputMat, state);
    }
    finishInputUpdate(input, inputMat, state);
    return loss;
  }
  void predict(const Vector& hidden, int32_t k, real threshold,
               std::vector<std::pair<real,int32_t>>& predictions,
               const std::shared_ptr<Matrix>& outputMat) const override {
    if (k == 0) throw std::invalid_argument("k needs to be 1 or higher!");
    Vector out(osz_); computeOutput(hidden, out, outputMat);
    std::vector<std::pair<real,int32_t>> scored;
    for (int32_t i = 0; i < osz_; i++) scored.push_back({out[(size_t)i], i});
    collectTopK(scored, k, threshold, predictions);
  }
};

class OneVsAllLoss : public BinaryLossBase {
 public:
  explicit OneVsAllLoss(int32_t osz) : BinaryLossBase(osz) {}
  void computeOutput(const Vector& hidden, Vector& out, const std::shared_ptr<Matrix>& outputMat) const override {
    out.zero();
    for (int32_t i = 0; i < osz_; i++) out[(size_t)i] = (real)sigmoid(outputMat->dotRow(hidden, i));
  }
  double update(const std::vector<int32_t>& input, int32_t target, real lr,
                const std::shared_ptr<Matrix>& inputMat,
                const std::shared_ptr<Matrix>& outputMat, ModelState& state,
                const std::vector<int32_t>& allTargets) override {
    state.grad.zero();
    double loss = 0;
    // target set: allTargets if non-empty, else single target
    auto isT = [&](int32_t i) {
      if (!allTargets.empty()) return std::find(allTargets.begin(), allTargets.end(), i) != allTargets.end();
      return i == target;
    };
    for (int32_t i = 0; i < osz_; i++) loss -= binaryLogistic(i, isT(i), lr, outputMat, state);
    finishInputUpdate(input, inputMat, state);
    return loss;
  }
  void predict(const Vector& hidden, int32_t k, real threshold,
               std::vector<std::pair<real,int32_t>>& predictions,
               const std::shared_ptr<Matrix>& outputMat) const override {
    if (k == 0) throw std::invalid_argument("k needs to be 1 or higher!");
    Vector out(osz_); computeOutput(hidden, out, outputMat);
    std::vector<std::pair<real,int32_t>> scored;
    for (int32_t i = 0; i < osz_; i++) scored.push_back({out[(size_t)i], i});
    collectTopK(scored, k, threshold, predictions);
  }
};

class HierarchicalSoftmaxLoss : public BinaryLossBase {
  struct Node { int32_t left = -1, right = -1, parent = -1; int64_t count = 0; };
  std::vector<Node> tree_;
  std::vector<std::vector<int32_t>> paths_; // per leaf: node row indices
  std::vector<std::vector<int8_t>> codes_; // per leaf: 1 if branch prob = sigmoid
 public:
  HierarchicalSoftmaxLoss(int32_t osz, const std::vector<int64_t>& counts) : BinaryLossBase(osz) { buildTree(counts); }
  void buildTree(const std::vector<int64_t>& counts) {
    paths_.assign((size_t)std::max(0, osz_), {});
    codes_.assign((size_t)std::max(0, osz_), {});
    if (osz_ <= 1) return;
    tree_.assign((size_t)(2 * osz_ - 1), Node());
    for (int32_t i = 0; i < osz_; i++) tree_[(size_t)i].count = counts[(size_t)i];
    for (int32_t i = osz_; i < 2 * osz_ - 1; i++) tree_[(size_t)i].count = (int64_t)1e15;
    int32_t leaf = osz_ - 1;
    int32_t nodeIdx = osz_;
    for (int32_t i = osz_; i < 2 * osz_ - 1; i++) {
      int32_t min1, min2;
      auto pick = [&]() -> int32_t {
        int32_t res;
        if (leaf >= 0 && tree_[(size_t)leaf].count < tree_[(size_t)nodeIdx].count) { res = leaf; leaf--; }
        else { res = nodeIdx; nodeIdx++; }
        return res;
      };
      min1 = pick(); min2 = pick();
      tree_[(size_t)i].left = min1;
      tree_[(size_t)i].right = min2;
      tree_[(size_t)min1].parent = i;
      tree_[(size_t)min2].parent = i;
      tree_[(size_t)i].count = tree_[(size_t)min1].count + tree_[(size_t)min2].count;
    }
    // paths: leaf -> root
    for (int32_t i = 0; i < osz_; i++) {
      int32_t cur = i;
      while (tree_[(size_t)cur].parent != -1) {
        int32_t p = tree_[(size_t)cur].parent;
        paths_[(size_t)i].push_back(p - osz_);
        // branch prob = sigmoid when cur is the 'right' child (min2)
        codes_[(size_t)i].push_back(tree_[(size_t)p].right == cur ? 1 : 0);
        cur = p;
      }
    }
  }
  void computeOutput(const Vector& hidden, Vector& out, const std::shared_ptr<Matrix>& outputMat) const override {
    out.zero();
    for (int32_t i = 0; i < osz_; i++) {
      double prob = 1.0;
      for (size_t j = 0; j < paths_[(size_t)i].size(); j++) {
        real score = outputMat->dotRow(hidden, paths_[(size_t)i][j]);
        double s = sigmoid(score);
        prob *= codes_[(size_t)i][j] ? s : (1.0 - s);
      }
      out[(size_t)i] = (real)prob;
    }
  }
  double update(const std::vector<int32_t>& input, int32_t target, real lr,
                const std::shared_ptr<Matrix>& inputMat,
                const std::shared_ptr<Matrix>& outputMat, ModelState& state,
                const std::vector<int32_t>&) override {
    state.grad.zero();
    double loss = 0;
    if (target >= 0 && target < osz_) {
      for (size_t j = 0; j < paths_[(size_t)target].size(); j++) {
        loss -= binaryLogistic(paths_[(size_t)target][j], codes_[(size_t)target][j] == 1, lr, outputMat, state);
      }
    }
    finishInputUpdate(input, inputMat, state);
    return loss;
  }
  void predict(const Vector& hidden, int32_t k, real threshold,
               std::vector<std::pair<real,int32_t>>& predictions,
               const std::shared_ptr<Matrix>& outputMat) const override {
    if (k == 0) throw std::invalid_argument("k needs to be 1 or higher!");
    Vector out(osz_); computeOutput(hidden, out, outputMat);
    std::vector<std::pair<real,int32_t>> scored;
    for (int32_t i = 0; i < osz_; i++) scored.push_back({out[(size_t)i], i});
    collectTopK(scored, k, threshold, predictions);
  }
};

// ------------------------------------------------------------- Meter
struct Meter {
  int64_t nexamples = 0;
  std::unordered_map<int32_t, int64_t> goldCounts, predCounts, tpCounts;
  int64_t totalGold = 0, totalPred = 0, totalTp = 0;
  // for standard P@k/R@k, the original counts per example as:
  // precision = correct / (nexamples * k?) handled in accessors below via sums
  std::vector<int32_t> labelOrder; // filled by caller if needed
  void update(const std::vector<int32_t>& gold, const std::vector<std::pair<real,int32_t>>& preds) {
    if (gold.empty()) return;
    nexamples++;
    std::unordered_set<int32_t> goldSet(gold.begin(), gold.end());
    std::unordered_set<int32_t> predSet;
    for (auto& p : preds) predSet.insert(p.second);
    for (auto g : goldSet) { goldCounts[g]++; totalGold++; }
    for (auto pr : predSet) { predCounts[pr]++; totalPred++; if (goldSet.count(pr)) { tpCounts[pr]++; totalTp++; } }
  }
  double precisionAt(int32_t) const {
    if (totalPred == 0 || nexamples == 0) return std::numeric_limits<double>::quiet_NaN();
    // Original generic precision: tp / number predicted (when k and threshold vary)
    // For standard test k=1 this equals tp/nexamples.
    return (double)totalTp / (double)totalPred;
  }
  // The original test output for P@k with k>1 uses tp / (nexamples * k) when
  // predictions are always k per example; our totalPred equals that in the
  // usual (no threshold) case. With threshold the denominator in the
  // original is nexamples * k as well; callers that need exactness pass k.
  double precisionAtK(int32_t k) const {
    if (nexamples == 0) return std::numeric_limits<double>::quiet_NaN();
    return (double)totalTp / ((double)nexamples * (double)k);
  }
  double recallAtK(int32_t) const {
    if (totalGold == 0 || nexamples == 0) return std::numeric_limits<double>::quiet_NaN();
    return (double)totalTp / (double)totalGold;
  }
  void writeGeneralMetrics(std::ostream& os, int32_t k) const {
    os << std::setprecision(3);
    os << "N\t" << nexamples << "\n";
    os << "P@" << k << "\t" << precisionAtK(k) << "\n";
    os << "R@" << k << "\t" << recallAtK(k) << "\n";
    // restore default formatting state choices used elsewhere
    os << std::setprecision(6);
  }
};

// ------------------------------------------------------------- FastText core
class FastText {
 public:
  std::shared_ptr<Args> args_;
  std::shared_ptr<Dictionary> dict_;
  std::shared_ptr<Matrix> input_;
  std::shared_ptr<Matrix> output_;
  std::shared_ptr<Loss> loss_;
  bool quant_ = false;
  int32_t version_ = 12;
  FastText() {}
  explicit FastText(std::shared_ptr<Args> a) : args_(a), dict_(std::make_shared<Dictionary>(a)) {}

  int32_t getOsz() const {
    if (!dict_) return 0;
    return args_->model == ModelName::sup ? dict_->nlabels() : dict_->nwords();
  }
  void createLoss() {
    int32_t osz = getOsz();
    auto counts = dict_->getCounts(args_->model == ModelName::sup ? EntryType::label : EntryType::word);
    if (args_->loss == LossName::softmax) loss_ = std::make_shared<SoftmaxLoss>(osz);
    else if (args_->loss == LossName::ns) loss_ = std::make_shared<NegativeSamplingLoss>(osz, args_->neg, counts);
    else if (args_->loss == LossName::ova) loss_ = std::make_shared<OneVsAllLoss>(osz);
    else if (args_->loss == LossName::hs) loss_ = std::make_shared<HierarchicalSoftmaxLoss>(osz, counts);
  }
  void getWordVector(Vector& vec, const std::string& word) const {
    vec.zero();
    auto ngrams = dict_->getSubwords(word);
    if (ngrams.empty()) return;
    for (auto id : ngrams) input_->addRowToVector(vec, id);
    vec.mul(1.0f / (real)ngrams.size());
  }
  void getWordVector(Vector& vec, int32_t id) const { getWordVector(vec, dict_->getWord(id)); }
  void computeHidden(const std::vector<int32_t>& input, Vector& hidden) const {
    hidden.zero();
    if (input.empty()) return;
    for (auto id : input) input_->addRowToVector(hidden, id);
    hidden.mul(1.0f / (real)input.size());
  }
  void getSentenceVectorFromLine(const std::vector<int32_t>& line, Vector& svec) const {
    svec.zero();
    if (line.empty()) return;
    if (args_->model == ModelName::sup) {
      computeHidden(line, svec);
    } else {
      // line is expected to be word ids in this overload when called internally
      // (not used by the stream version below for unsupervised models)
      computeHidden(line, svec);
    }
  }
  // stream version - dispatches on model type as observed
  void getSentenceVector(LineReader& reader, Vector& svec) const {
    svec.zero();
    if (args_->model == ModelName::sup) {
      std::vector<int32_t> line, labels;
      dict_->getLine(reader, line, labels);
      if (line.empty()) return;
      computeHidden(line, svec);
    } else {
      // read a raw line of tokens (until EOS), each token's (normalised)
      // word vector contributes equally
      std::vector<std::string> tokens;
      std::string token;
      // We need token-level reading, not subword-expanded line. Reuse reader:
      while (reader.readWord(token)) {
        if (token == EOS) break;
        tokens.push_back(token);
      }
      if (tokens.empty()) return;
      Vector vec(args_->dim);
      for (auto& w : tokens) {
        getWordVector(vec, w);
        vec.normalize();
        svec.addVector(vec);
      }
      svec.mul(1.0f / (real)tokens.size());
    }
  }
  bool predictOne(const std::vector<int32_t>& line, int32_t k, real threshold,
                  std::vector<std::pair<real,int32_t>>& predictions) const {
    predictions.clear();
    if (line.empty()) return false;
    if (!loss_) return false;
    Vector hidden(args_->dim);
    computeHidden(line, hidden);
    loss_->predict(hidden, k, threshold, predictions, output_);
    return !predictions.empty();
  }
  void test(LineReader& reader, int32_t k, real threshold, Meter& meter, bool printMetricsLabels, std::ostream& out);
  void saveModel(std::ostream& out);
  void loadModel(const std::string& filename);
  void saveVectors(const std::string& filename);
  void saveOutput(const std::string& filename);
  void trainThread(int threadId, int64_t fileSize, std::atomic<int64_t>& totalTokensProcessed,
                   std::atomic<double>& totalLoss, std::atomic<int64_t>& totalExamplesForLoss,
                   double& sharedProgress, bool isAutotuneTrial);
  void train(const std::string& inputPathForAutotuneCheck = "");
  void quantizeModel(const Args& qargs, const std::string& trainFile);
  std::vector<int32_t> selectEmbeddings(int32_t cutoff) const;
  double evaluatePretrainedOrAutotune(const std::string& validFile, int32_t k, const std::string& metric, int32_t& outGoldTotal);
};

