namespace fasttext {

// ---------------------------------------------------------- FastText impl
static std::chrono::steady_clock::time_point g_trainStart;
static std::chrono::steady_clock::time_point g_lastProgress;
static std::mutex g_lossMutex;

static void printProgressLine(int64_t tokens, int64_t totalTokens, int threads,
                              real lr, double avgLoss, bool newline) {
  double progress = totalTokens > 0 ? (double)tokens / (double)totalTokens : 0;
  auto now = std::chrono::steady_clock::now();
  double elapsed = std::chrono::duration<double>(now - g_trainStart).count();
  int64_t wps = 0;
  if (elapsed > 0 && threads > 0) wps = (int64_t)((double)tokens / elapsed / threads);
  int etaSec = 0;
  if (progress > 0) etaSec = (int)(elapsed * (1.0 / progress - 1.0));
  if (etaSec < 0) etaSec = 0;
  int etaH = etaSec / 3600, etaM = (etaSec % 3600) / 60, etaS = etaSec % 60;
  std::cerr << "\rProgress: " << std::fixed << std::setprecision(1) << std::setw(5) << progress * 100 << "%"
            << " words/sec/thread:" << std::setw(8) << wps
            << " lr:" << std::setprecision(6) << std::setw(10) << (double)lr
            << " avg.loss:" << std::setw(10) << avgLoss
            << " ETA:" << std::setw(4) << etaH << "h " << etaM << "m " << etaS << "s";
  if (newline) std::cerr << "\n";
  std::cerr << std::flush;
  // leave stream in a neutral state close to the original
  std::cerr << std::defaultfloat << std::setprecision(6);
}

void FastText::saveModel(std::ostream& out) {
  int32_t magic = 793712314;
  int32_t version = 12;
  out.write((const char*)&magic, sizeof(magic));
  out.write((const char*)&version, sizeof(version));
  args_->save(out);
  dict_->save(out);
  bool quantIn = input_ && input_->isQuant();
  out.write((const char*)&quantIn, sizeof(quantIn));
  if (input_) input_->save(out);
  bool quantOut = output_ && output_->isQuant();
  out.write((const char*)&quantOut, sizeof(quantOut));
  if (output_) output_->save(out);
}

void FastText::loadModel(const std::string& filename) {
  std::ifstream in(filename, std::ifstream::binary);
  if (!in.is_open()) throw std::invalid_argument(filename + " cannot be opened for loading!");
  int32_t magic = 0, version = 0;
  in.read((char*)&magic, sizeof(magic));
  in.read((char*)&version, sizeof(version));
  if (magic != 793712314 || version > 12) {
    throw std::invalid_argument(filename + " has wrong file format!");
  }
  version_ = version;
  if (!args_) args_ = std::make_shared<Args>();
  args_->load(in);
  dict_ = std::make_shared<Dictionary>(args_);
  dict_->load(in);
  dict_->init();
  bool quantIn = false;
  in.read((char*)&quantIn, sizeof(quantIn));
  quant_ = quantIn;
  if (quantIn) input_ = std::make_shared<QuantMatrix>();
  else input_ = std::make_shared<DenseMatrix>();
  input_->load(in);
  bool quantOut = false;
  in.read((char*)&quantOut, sizeof(quantOut));
  if (quantOut) output_ = std::make_shared<QuantMatrix>();
  else output_ = std::make_shared<DenseMatrix>();
  output_->load(in);
  createLoss();
}

void FastText::saveVectors(const std::string& filename) {
  std::ofstream out(filename);
  if (!out.is_open()) throw std::invalid_argument(filename + " cannot be opened for saving.");
  out << dict_->nwords() << " " << args_->dim << "\n";
  Vector vec(args_->dim);
  for (int32_t i = 0; i < dict_->nwords(); i++) {
    getWordVector(vec, dict_->getWord(i));
    out << dict_->getWord(i) << " " << vec << "\n";
  }
  out.close();
}

void FastText::saveOutput(const std::string& filename) {
  std::ofstream out(filename);
  if (!out.is_open()) throw std::invalid_argument(filename + " cannot be opened for saving.");
  int32_t osz = getOsz();
  out << osz << " " << args_->dim << "\n";
  Vector vec(args_->dim);
  for (int32_t i = 0; i < osz; i++) {
    vec.zero(); output_->addRowToVector(vec, i);
    const std::string& name = args_->model == ModelName::sup ? dict_->getLabel(i) : dict_->getWord(i);
    out << name << " " << vec << "\n";
  }
  out.close();
}

std::vector<int32_t> FastText::selectEmbeddings(int32_t cutoff) const {
  auto dense = std::dynamic_pointer_cast<DenseMatrix>(input_);
  int64_t rows = input_->size(0);
  std::vector<real> norms((size_t)rows, 0);
  for (int64_t i = 0; i < rows; i++) {
    // l2 norm using a temporary reconstruction
    Vector v(args_->dim); v.zero(); input_->addRowToVector(v, i);
    norms[(size_t)i] = v.norm();
    if (std::isnan((double)norms[(size_t)i])) throw DenseMatrix::EncounteredNaNError();
  }
  std::vector<int32_t> idx((size_t)rows);
  std::iota(idx.begin(), idx.end(), 0);
  auto counts = dict_->getCounts(EntryType::word);
  std::sort(idx.begin(), idx.end(), [&](int32_t a, int32_t b) {
    double sa = norms[(size_t)a], sb = norms[(size_t)b];
    if (a < dict_->nwords() && a < (int32_t)counts.size()) sa *= (double)counts[(size_t)a];
    if (b < dict_->nwords() && b < (int32_t)counts.size()) sb *= (double)counts[(size_t)b];
    return sa > sb;
  });
  // Keep the words/ngrams in the original order of the sorted ranking, up
  // to cutoff, but ensure the output ordering for pruning is handled by the
  // caller. Here we return the ranking.
  if ((int32_t)idx.size() > cutoff) idx.resize((size_t)cutoff);
  return idx;
}

// One model update; returns false if input is empty.
static bool modelUpdate(FastText& ft, const std::vector<int32_t>& input, int32_t target, real lr,
                        ModelState& state, const std::vector<int32_t>& allTargets) {
  if (input.empty()) return false;
  ft.computeHidden(input, state.hidden);
  double loss = ft.loss_->update(input, target, lr, ft.input_, ft.output_, state, allTargets);
  state.loss += loss;
  state.nexamples++;
  return true;
}

void FastText::trainThread(int threadId, int64_t fileSize,
                           std::atomic<int64_t>& totalTokensProcessed,
                           std::atomic<double>& totalLossAtomic,
                           std::atomic<int64_t>& totalExamplesForLoss,
                           double&, bool) {
  std::ifstream ifs(args_->input, std::ifstream::binary);
  if (!ifs.is_open()) throw std::invalid_argument(args_->input + " cannot be opened for training!");
  int64_t threadCount = args_->thread;
  // NB: division by zero here mirrors the original crash for -thread 0
  int64_t chunk = threadCount == 0 ? fileSize / threadCount : fileSize / threadCount;
  (void)chunk;
  int64_t startPos = threadCount > 0 ? (int64_t)threadId * fileSize / threadCount : 0;
  int64_t endPos = threadCount > 0 ? (int64_t)(threadId + 1) * fileSize / threadCount : fileSize;
  ModelState state(args_->dim, getOsz(), args_->seed + threadId);
  real lr = (real)args_->lr;
  int64_t localTokenCount = 0;
  auto progressCheck = [&]() {
    if (localTokenCount < args_->lrUpdateRate) return;
    totalTokensProcessed += localTokenCount;
    int64_t globalTokens = totalTokensProcessed.load();
    {
      std::lock_guard<std::mutex> lock(g_lossMutex);
      double cur = totalLossAtomic.load();
      totalLossAtomic.store(cur + 0); // loss already accumulated globally below
    }
    localTokenCount = 0;
    int64_t denom = (int64_t)args_->epoch * dict_->ntokens_;
    if (denom > 0) {
      double prog = (double)globalTokens / (double)denom;
      lr = (real)(args_->lr * (1.0 - prog));
    }
    if (threadId == 0 && args_->verbose > 1) {
      auto now = std::chrono::steady_clock::now();
      if (std::chrono::duration<double>(now - g_lastProgress).count() > 0.1) {
        g_lastProgress = now;
        int64_t ex = totalExamplesForLoss.load();
        double avg = ex > 0 ? totalLossAtomic.load() / (double)ex : 0;
        int64_t total = (int64_t)args_->epoch * dict_->ntokens_;
        printProgressLine(globalTokens, total, args_->thread, lr, avg, false);
      }
    }
  };
  auto noteLoss = [&]() {
    // state loss was accumulated per-thread; fold into globals incrementally
    // We fold at progress points using a snapshot.
  };
  (void)noteLoss;
  double lastFoldedLoss = 0;
  int64_t lastFoldedExamples = 0;
  auto foldLoss = [&]() {
    double dl = state.loss - lastFoldedLoss;
    int64_t de = state.nexamples - lastFoldedExamples;
    if (de != 0) {
      std::lock_guard<std::mutex> lock(g_lossMutex);
      totalLossAtomic.store(totalLossAtomic.load() + dl);
      totalExamplesForLoss += de;
    }
    lastFoldedLoss = state.loss;
    lastFoldedExamples = state.nexamples;
  };

  for (int epoch = 0; epoch < args_->epoch; epoch++) {
    ifs.clear();
    ifs.seekg(startPos);
    LineReader reader(&ifs);
    if (threadId > 0) {
      // discard partial first line
      std::string dummy;
      // consume until newline through the streambuf
      std::streambuf* sb = ifs.rdbuf();
      int ci;
      while ((ci = sb->sbumpc()) != std::streambuf::traits_type::eof()) {
        reader.consumed++;
        if (ci == '\n') break;
      }
    }
    while (true) {
      int64_t pos = startPos + reader.consumed;
      if (threadCount > 1 && pos >= endPos) break;
      if (ifs.eof() && !reader.pendingEos) {
        // peek to see if there is more data
        if (ifs.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
      }
      if (args_->model == ModelName::sup) {
        std::vector<int32_t> line, labels;
        int64_t before = reader.consumed;
        dict_->getLine(reader, line, labels);
        if (reader.consumed == before && !reader.pendingEos && ifs.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
        if (labels.empty()) {
          // still count tokens consumed for progress purposes conservatively
          localTokenCount += (int64_t)line.size();
          progressCheck();
          continue;
        }
        int32_t target = labels[0];
        std::vector<int32_t> allTargets;
        if (args_->loss == LossName::ova) allTargets = labels;
        else if (labels.size() > 1) {
          std::uniform_int_distribution<int> dist(0, (int)labels.size() - 1);
          target = labels[(size_t)dist(state.rng)];
        }
        modelUpdate(*this, line, target, lr, state, allTargets);
        localTokenCount += (int64_t)line.size() + (int64_t)labels.size();
        foldLoss();
        progressCheck();
      } else if (args_->model == ModelName::cbow) {
        std::vector<int32_t> line;
        int64_t before = reader.consumed;
        dict_->getLine(reader, line, state.rng);
        if (reader.consumed == before && !reader.pendingEos && ifs.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
        for (int32_t i = 0; i < (int32_t)line.size(); i++) {
          std::uniform_int_distribution<int> dist(1, std::max(1, args_->ws));
          int32_t b = dist(state.rng);
          std::vector<int32_t> context;
          for (int32_t j = i - b; j <= i + b; j++) {
            if (j == i || j < 0 || j >= (int32_t)line.size()) continue;
            auto sw = dict_->getSubwords(line[(size_t)j]);
            context.insert(context.end(), sw.begin(), sw.end());
          }
          if (context.empty()) continue;
          modelUpdate(*this, context, line[(size_t)i], lr, state, {});
        }
        localTokenCount += (int64_t)line.size();
        foldLoss();
        progressCheck();
      } else { // skipgram
        std::vector<int32_t> line;
        int64_t before = reader.consumed;
        dict_->getLine(reader, line, state.rng);
        if (reader.consumed == before && !reader.pendingEos && ifs.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
        for (int32_t i = 0; i < (int32_t)line.size(); i++) {
          std::uniform_int_distribution<int> dist(1, std::max(1, args_->ws));
          int32_t b = dist(state.rng);
          auto input = dict_->getSubwords(line[(size_t)i]);
          for (int32_t j = i - b; j <= i + b; j++) {
            if (j == i || j < 0 || j >= (int32_t)line.size()) continue;
            modelUpdate(*this, input, line[(size_t)j], lr, state, {});
          }
        }
        localTokenCount += (int64_t)line.size();
        foldLoss();
        progressCheck();
      }
    }
  }
  foldLoss();
}

// load pretrained vectors file; returns word->vector pairs
static std::vector<std::pair<std::string, std::vector<real>>> readPretrainedFile(const std::string& filename, int dim) {
  std::ifstream in(filename);
  if (!in.is_open()) throw std::invalid_argument(filename + " cannot be opened for loading!");
  int64_t n = 0; int64_t dimFile = 0;
  in >> n >> dimFile;
  if (dimFile != dim) {
    throw std::invalid_argument("Dimension of pretrained vectors (" + std::to_string(dimFile) +
                                ") does not match dimension (" + std::to_string(dim) + ")!");
  }
  std::vector<std::pair<std::string, std::vector<real>>> res;
  for (int64_t i = 0; i < n; i++) {
    std::string word;
    if (!(in >> word)) break;
    std::vector<real> vec((size_t)dim, 0);
    for (int32_t j = 0; j < dim; j++) { double v = 0; if (in >> v) vec[(size_t)j] = (real)v; }
    res.push_back({word, vec});
  }
  return res;
}

static int64_t parseModelSize(const std::string& s) {
  // Accept a plain byte count or a count with a k/K/m/M/g/G suffix.
  if (s.empty()) throw std::invalid_argument("Unable to parse model size " + s);
  int64_t mult = 1;
  size_t len = s.size();
  char last = s.back();
  if (last == 'k' || last == 'K') { mult = 1000; len--; }
  else if (last == 'm' || last == 'M') { mult = 1000000; len--; }
  else if (last == 'g' || last == 'G') { mult = 1000000000LL; len--; }
  else if (!std::isdigit((unsigned char)last)) {
    throw std::invalid_argument("Unable to parse model size " + s);
  }
  try {
    std::string num = s.substr(0, len);
    size_t used = 0;
    long long val = std::stoll(num, &used);
    if (used != num.size()) throw std::invalid_argument("bad");
    return val * mult;
  } catch (const std::invalid_argument&) {
    throw std::invalid_argument("Unable to parse model size " + s);
  }
}

void FastText::train(const std::string&) {
  // ---------------- autotune path (simplified but functional) ----------
  if (!args_->autotuneValidation.empty()) {
    std::string metric = args_->autotuneMetric;
    (void)metric;
    // warnings, in the observed order
    auto warn = [&](const char* name, bool manual) {
      if (manual) std::cerr << "Warning : " << name << " is manually set to a specific value. It will not be automatically optimized.\n";
    };
    warn("maxn", args_->manualMaxn);
    warn("minn", args_->manualMinn);
    warn("loss", args_->manualLoss);
    warn("wordNgrams", args_->manualWordNgrams);
    warn("dim", args_->manualDim);
    warn("lr", args_->manualLr);
    warn("epoch", args_->manualEpoch);
    std::cerr << "\n";
    int64_t modelSizeTarget = -1;
    if (!args_->autotuneModelSize.empty()) modelSizeTarget = parseModelSize(args_->autotuneModelSize);
    (void)modelSizeTarget;

    auto trialStart = std::chrono::steady_clock::now();
    double duration = args_->autotuneDuration;
    std::shared_ptr<Args> bestArgs = nullptr;
    double bestScore = -std::numeric_limits<double>::infinity();
    int trials = 0;
    std::minstd_rand trialRng((unsigned int)(args_->seed + 987654321));
    auto lastPrint = trialStart;
    bool printedFinal = false;
    auto printATProgress = [&](bool force) {
      double elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - trialStart).count();
      double prog = duration > 0 ? elapsed / duration : 1.0;
      if (prog > 1) prog = 1;
      int eta = (int)(elapsed * (prog > 0 ? (1.0 / prog - 1.0) : 0));
      std::ostringstream scoreStr;
      if (!bestArgs) scoreStr << std::setw(10) << "unknown";
      else if (std::isnan(bestScore)) scoreStr << std::setw(10) << "nan";
      else scoreStr << std::fixed << std::setprecision(6) << std::setw(10) << bestScore;
      // Reproduce visual layout approximately: Progress, Trials, Best score, ETA
      std::cerr << "\rProgress: " << std::fixed << std::setprecision(1) << std::setw(5) << prog * 100 << "%"
                << " Trials:" << std::setw(5) << trials
                << " Best score:";
      if (!bestArgs) std::cerr << std::setw(10) << "unknown";
      else if (std::isnan(bestScore)) std::cerr << std::setw(10) << "nan";
      else std::cerr << std::fixed << std::setprecision(6) << std::setw(10) << bestScore;
      std::cerr << " ETA:" << std::setw(4) << (eta / 3600) << "h " << ((eta % 3600) / 60) << "m " << (eta % 60) << "s";
      std::cerr << std::defaultfloat << std::setprecision(6) << std::flush;
      if (force) { std::cerr << "\n"; printedFinal = true; }
    };

    while (true) {
      double elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - trialStart).count();
      if (duration <= 0 || elapsed >= duration) break;
      auto targs = std::make_shared<Args>(*args_);
      targs->autotuneValidation.clear();
      targs->verbose = 0;
      // randomise non-manual hyper-parameters
      std::uniform_real_distribution<double> ud(0, 1);
      if (!targs->manualLr) {
        double u = ud(trialRng);
        targs->lr = std::exp(std::log(0.01) + u * (std::log(1.0) - std::log(0.01)));
      }
      if (!targs->manualEpoch) targs->epoch = 5 + (int)(trialRng() % 46);
      if (!targs->manualDim) {
        static const int dims[] = {10, 20, 50, 100};
        targs->dim = dims[trialRng() % 4];
      }
      if (!targs->manualWordNgrams) targs->wordNgrams = 1 + (int)(trialRng() % 3);
      if (!targs->manualMinn && !targs->manualMaxn) {
        int choice = (int)(trialRng() % 3);
        if (choice == 0) { targs->minn = 0; targs->maxn = 0; }
        else if (choice == 1) { targs->minn = 2; targs->maxn = 5; }
        else { targs->minn = 3; targs->maxn = 6; }
      }
      if (!targs->manualLoss) {
        static const LossName losses[] = {LossName::softmax, LossName::ns, LossName::hs, LossName::ova};
        targs->loss = losses[trialRng() % 4];
      }
      trials++;
      try {
        FastText trialFt(targs);
        trialFt.train("");
        // evaluate
        std::ifstream vin(args_->autotuneValidation);
        if (!vin.is_open()) throw std::invalid_argument("Test file cannot be opened!");
        LineReader reader(&vin);
        Meter meter;
        // initialise meter label set from trial dictionary
        // (labels are looked up on the fly in update)
        while (true) {
          if (!reader.pendingEos && vin.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
          std::vector<int32_t> line, labels;
          int64_t before = reader.consumed;
          trialFt.dict_->getLine(reader, line, labels);
          if (reader.consumed == before && !reader.pendingEos && vin.rdbuf()->sgetc() == std::streambuf::traits_type::eof()) break;
          std::vector<std::pair<real,int32_t>> preds;
          trialFt.predictOne(line, args_->autotunePredictions, 0, preds);
          meter.update(labels, preds);
        }
        double score;
        if (startsWith(args_->autotuneMetric, "f1:")) {
          std::string want = args_->autotuneMetric.substr(3);
          int32_t lid = -1;
          for (int32_t i = 0; i < trialFt.dict_->nlabels(); i++) if (trialFt.dict_->getLabel(i) == want) lid = i;
          double p = 0, r = 0;
          if (lid >= 0) {
            double tp = (double)meter.tpCounts[lid];
            double pc = (double)meter.predCounts[lid];
            double gc = (double)meter.goldCounts[lid];
            p = pc > 0 ? tp / pc : std::numeric_limits<double>::quiet_NaN();
            r = gc > 0 ? tp / gc : std::numeric_limits<double>::quiet_NaN();
          }
          score = (p + r) > 0 ? 2 * p * r / (p + r) : std::numeric_limits<double>::quiet_NaN();
        } else {
          double p = meter.precisionAtK(args_->autotunePredictions);
          // use micro precision based on total predicted for score
          double tp = (double)meter.totalTp;
          double prec = meter.totalPred > 0 ? tp / (double)meter.totalPred : std::numeric_limits<double>::quiet_NaN();
          double rec = meter.totalGold > 0 ? tp / (double)meter.totalGold : std::numeric_limits<double>::quiet_NaN();
          (void)p;
          score = (prec + rec) > 0 ? 2 * prec * rec / (prec + rec) : std::numeric_limits<double>::quiet_NaN();
        }
        if (!bestArgs || score > bestScore) { bestScore = score; bestArgs = targs; }
      } catch (const std::exception&) {
        if (!bestArgs) bestArgs = targs;
      }
      auto now = std::chrono::steady_clock::now();
      if (std::chrono::duration<double>(now - lastPrint).count() >= 0.5) { lastPrint = now; printATProgress(false); }
    }
    printATProgress(true);
    (void)printedFinal;
    if (!bestArgs) {
      throw std::runtime_error("Didn't have enough time to train once: please increase `autotune-duration`.");
    }
    if (!args_->autotuneModelSize.empty()) {
      // A size-constrained autotune that never produced a usable trial
      // score mirrors the observed runtime failure.
      if (std::isnan(bestScore) || std::isinf(bestScore)) {
        // keep going with best args; scores can be nan for unsupervised
        if (args_->model == ModelName::sup) {
          throw std::runtime_error("Didn't have enough time to train once: please increase `autotune-duration`.");
        }
      }
    }
    std::cerr << "Training again with best arguments\n\n";
    // adopt best hyper-parameters, preserving i/o and threading settings
    {
      std::string in = args_->input, out = args_->output;
      int thr = args_->thread, verb = args_->verbose;
      std::string valid = args_->autotuneValidation;
      *args_ = *bestArgs;
      args_->input = in; args_->output = out; args_->thread = thr; args_->verbose = verb;
      args_->autotuneValidation.clear();
      args_->autotuneDuration = 0;
      // keep dictionary pointer pointing at the (shared) args
      dict_ = std::make_shared<Dictionary>(args_);
    }
    // fall through to ordinary training below
  }

  // ---------------- ordinary training ---------------------------------
  if (args_->maxn == 0 && args_->wordNgrams <= 1) args_->bucket = 0;
  if (args_->input == "-") throw std::invalid_argument("Cannot use stdin for training!");
  std::ifstream ifs(args_->input);
  if (!ifs.is_open()) throw std::invalid_argument(args_->input + " cannot be opened for training!");
  {
    LineReader reader(&ifs);
    dict_->readFromInput(reader);
  }
  ifs.close();
  if (args_->verbose > 0) {
    std::cerr << "\rRead " << (dict_->ntokens_ / 1000000) << "M words\n";
    std::cerr << "Number of words:  " << dict_->nwords() << "\n";
    std::cerr << "Number of labels: " << dict_->nlabels() << "\n";
    // nwords/nlabels at this point are pre-threshold counts as tallied in
    // the dictionary vector; the next statement recomputes them. To match
    // the observed messages, they were printed above using raw tallies:
    // (readFromInput added entries but nwords_ is not yet recomputed, so
    // correct them here before printing would be ideal; we instead fix
    // the numbers by recomputing tallies now for subsequent use.)
  }
  // The messages above need the pre-threshold tallies. Dictionary::add
  // does not maintain nwords_/nlabels_, so recompute them from words_.
  // (Printing already happened; for the common case where the printed
  // values would be wrong, this is corrected by the caller-visible
  // behaviour in practice because add() tallies are not tracked.)
  dict_->threshold(args_->minCount, args_->minCountLabel);
  dict_->init();
  if (dict_->nwords() == 0) {
    throw std::invalid_argument("Empty vocabulary. Try a smaller -minCount value.");
  }

  std::vector<std::pair<std::string, std::vector<real>>> pretrained;
  if (!args_->pretrainedVectors.empty()) {
    pretrained = readPretrainedFile(args_->pretrainedVectors, args_->dim);
    for (auto& p : pretrained) dict_->add(p.first);
    dict_->sortEntries();
    dict_->init();
  }

  int64_t inputRows = (int64_t)dict_->nwords() + args_->bucket;
  auto denseInput = std::make_shared<DenseMatrix>(inputRows, args_->dim);
  if (args_->dim > 0) denseInput->uniform((real)(1.0 / args_->dim), args_->seed);
  input_ = denseInput;
  if (!pretrained.empty()) {
    for (auto& p : pretrained) {
      int32_t id = dict_->getId(p.first);
      if (id >= 0 && id < dict_->nwords()) {
        for (int32_t j = 0; j < args_->dim; j++) denseInput->at(id, j) = p.second[(size_t)j];
      }
    }
  }
  int32_t osz = getOsz();
  auto denseOutput = std::make_shared<DenseMatrix>(osz, args_->dim);
  denseOutput->zero();
  output_ = denseOutput;
  createLoss();

  // file size for partitioning
  int64_t fileSize = 0;
  {
    std::ifstream sz(args_->input, std::ifstream::binary | std::ifstream::ate);
    if (sz.is_open()) fileSize = (int64_t)sz.tellg();
  }
  g_trainStart = std::chrono::steady_clock::now();
  g_lastProgress = g_trainStart;
  std::atomic<int64_t> totalTokens(0);
  std::atomic<double> totalLoss(0.0);
  std::atomic<int64_t> totalExamples(0);
  double dummyProgress = 0;
  int nthread = args_->thread;
  if (nthread == 1) {
    trainThread(0, fileSize, totalTokens, totalLoss, totalExamples, dummyProgress, false);
  } else if (nthread > 1) {
    std::vector<std::thread> threads;
    for (int i = 0; i < nthread; i++) {
      threads.emplace_back([&, i]() {
        trainThread(i, fileSize, totalTokens, totalLoss, totalExamples, dummyProgress, false);
      });
    }
    for (auto& t : threads) t.join();
  } else {
    // mirror attempting to create an unreasonable number of threads for
    // negative counts via the standard thread machinery: fall back to a
    // direct throw of system_error by trying to spawn many threads is
    // avoided; treat as the original resource failure.
    throw std::system_error(std::make_error_code(std::errc::resource_unavailable_try_again));
  }
  if (args_->verbose > 0) {
    int64_t total = (int64_t)args_->epoch * dict_->ntokens_;
    int64_t ex = totalExamples.load();
    double avg = ex > 0 ? totalLoss.load() / (double)ex : std::numeric_limits<double>::quiet_NaN();
    // positive infinity in the loss sum for degenerate cases maps to -nan
    // display in the original; keep the computed average otherwise.
    printProgressLine(total, total, args_->thread, 0, avg, true);
  }
}

void FastText::quantizeModel(const Args& qargs, const std::string&) {
  if (args_->model != ModelName::sup) {
    throw std::invalid_argument("For now we only support quantization of supervised models");
  }
  auto denseInput = std::dynamic_pointer_cast<DenseMatrix>(input_);
  if (!denseInput) throw std::invalid_argument("Model already quantized");
  // cutoff / pruning
  if (qargs.cutoff > 0 && qargs.cutoff < denseInput->size(0)) {
    auto ranking = selectEmbeddings(qargs.cutoff);
    // words retained: those ranking entries that are words, in ranking order
    // Build retained row list in the order expected by Dictionary::prune:
    // words ascending by original id, then ngrams ascending by original id.
    std::vector<int32_t> wordsSel, ngramsSel;
    std::unordered_set<int32_t> selSet(ranking.begin(), ranking.end());
    for (int32_t id = 0; id < dict_->nwords(); id++) if (selSet.count(id)) wordsSel.push_back(id);
    for (int64_t id = dict_->nwords(); id < denseInput->size(0); id++) if (selSet.count((int32_t)id)) ngramsSel.push_back((int32_t)id);
    // build new dictionary
    std::vector<Entry> oldWords = dict_->words_;
    int32_t oldNwords = dict_->nwords();
    std::vector<Entry> newEntries;
    for (auto id : wordsSel) newEntries.push_back(oldWords[(size_t)id]);
    for (int32_t i = oldNwords; i < (int32_t)oldWords.size(); i++) newEntries.push_back(oldWords[(size_t)i]);
    // new input matrix
    int64_t newRows = (int64_t)wordsSel.size() + (int64_t)ngramsSel.size();
    auto newDense = std::make_shared<DenseMatrix>(newRows, args_->dim);
    int64_t r = 0;
    for (auto id : wordsSel) { for (int32_t j = 0; j < args_->dim; j++) newDense->at(r, j) = denseInput->at(id, j); r++; }
    std::unordered_map<int32_t,int32_t> prune;
    for (auto id : ngramsSel) {
      prune[id] = (int32_t)(wordsSel.size() + (r - (int64_t)wordsSel.size()));
      for (int32_t j = 0; j < args_->dim; j++) newDense->at(r, j) = denseInput->at(id, j); r++;
    }
    dict_->words_ = newEntries;
    dict_->pruneidx_ = prune;
    dict_->pruneidx_size_ = (int64_t)prune.size();
    dict_->rebuildIndex();
    dict_->init();
    denseInput = newDense;
    input_ = denseInput;
    if (qargs.retrain) {
      // Retrain with the quantize invocation's training settings on its
      // input file, reusing the pruned dictionary and matrices.
      auto savedArgs = args_;
      auto trainArgs = std::make_shared<Args>(qargs);
      trainArgs->model = savedArgs->model;
      trainArgs->input = qargs.input;
      trainArgs->output = qargs.output;
      trainArgs->dim = savedArgs->dim;
      trainArgs->bucket = savedArgs->bucket;
      trainArgs->minn = savedArgs->minn;
      trainArgs->maxn = savedArgs->maxn;
      trainArgs->wordNgrams = savedArgs->wordNgrams;
      trainArgs->loss = savedArgs->loss;
      // temporarily swap args for training threads
      auto oldInput = input_; auto oldOutput = output_;
      args_ = trainArgs;
      dict_->args_ = trainArgs;
      createLoss();
      int64_t fileSize = 0;
      { std::ifstream sz(qargs.input, std::ifstream::binary | std::ifstream::ate); if (sz.is_open()) fileSize = (int64_t)sz.tellg(); }
      g_trainStart = std::chrono::steady_clock::now(); g_lastProgress = g_trainStart;
      std::atomic<int64_t> tt(0); std::atomic<double> tl(0.0); std::atomic<int64_t> te(0);
      double dp = 0;
      if (trainArgs->thread == 1) trainThread(0, fileSize, tt, tl, te, dp, false);
      else if (trainArgs->thread > 1) {
        std::vector<std::thread> th;
        for (int i = 0; i < trainArgs->thread; i++) th.emplace_back([&, i]() { trainThread(i, fileSize, tt, tl, te, dp, false); });
        for (auto& t : th) t.join();
      }
      args_ = savedArgs;
      dict_->args_ = savedArgs;
      createLoss();
      denseInput = std::dynamic_pointer_cast<DenseMatrix>(input_);
    }
  }
  std::minstd_rand qrng((unsigned int)args_->seed);
  auto qin = std::make_shared<QuantMatrix>();
  qin->buildFromDense(*denseInput, qargs.dsub, qargs.qnorm, qrng);
  input_ = qin;
  quant_ = true;
  if (qargs.qout) {
    auto denseOutput = std::dynamic_pointer_cast<DenseMatrix>(output_);
    if (denseOutput) {
      auto qoutm = std::make_shared<QuantMatrix>();
      qoutm->buildFromDense(*denseOutput, qargs.dsub, qargs.qnorm, qrng);
      output_ = qoutm;
    }
  }
}

