#include <bits/stdc++.h>
using namespace std;
const char* words[]={"the","quick","brown","fox","jumps","over","lazy","dog","and","cat","runs","fast","</s>"};
void show(string name, vector<int> idx){ cout<<name<<": "; for(int i:idx) cout<<words[i]<<" "; cout<<"\n"; }
int main(){
 for(int K:{3,10}){
   // bounded min-heap via priority_queue greater
   using P=pair<float,int>;
   priority_queue<P, vector<P>, function<bool(const P&,const P&)>> pq([](const P&a,const P&b){return a.first>b.first;});
   for(int i=0;i<13;i++){ pq.push({0,i}); if((int)pq.size()>K) pq.pop(); }
   vector<int> out; while(!pq.empty()){out.push_back(pq.top().second); pq.pop();}
   reverse(out.begin(), out.end()); show("bounded-minheap-rev K="+to_string(K), out);
 }
 for(int K:{3,10}){
   using P=pair<float,int>;
   priority_queue<P, vector<P>, function<bool(const P&,const P&)>> pq([](const P&a,const P&b){return a.first<b.first;}); // max
   for(int i=0;i<13;i++){ pq.push({0,i}); if((int)pq.size()>K) pq.pop(); }
   vector<int> out; while(!pq.empty()){out.push_back(pq.top().second); pq.pop();}
   show("bounded-maxheap K="+to_string(K), out);
 }
 for(int K:{3,10}){
   // nth_element + sort
   vector<pair<float,int>> v; for(int i=0;i<13;i++) v.push_back({0,i});
   nth_element(v.begin(), v.begin()+K, v.end(), [](auto&a,auto&b){return a.first>b.first;});
   sort(v.begin(), v.begin()+K, [](auto&a,auto&b){return a.first>b.first;});
   vector<int> out; for(int i=0;i<K;i++) out.push_back(v[i].second); show("nth+sort K="+to_string(K), out);
 }
 for(int K:{3,10}){
   vector<pair<float,int>> v; for(int i=0;i<13;i++) v.push_back({0,i});
   partial_sort(v.begin(), v.begin()+K, v.end(), [](auto&a,auto&b){return a.first>b.first;});
   vector<int> out; for(int i=0;i<K;i++) out.push_back(v[i].second); show("partial_sort K="+to_string(K), out);
 }
}
