      }
      exit(1);
    }
    auto ft = loadModelOrThrow(cargs[0]);
    int32_t k = cargs.size() >= 3 ? std::stoi(cargs[2]) : 1;
    real th = cargs.size() >= 4 ? std::stof(cargs[3]) : 0;
    std::string inputFile = cargs[1];
