    auto ft = loadModelOrThrow(cargs[0]);
    int32_t k = cargs.size() >= 3 ? std::stoi(cargs[2]) : 1;
    real th = cargs.size() >= 4 ? std::stof(cargs[3]) : 0;
    std::ifstream ifs;
    std::istream* inPtr = nullptr;
    if (cargs[1] == "-") inPtr = &std::cin;
    else {
      ifs.open(cargs[1]);
      if (!ifs.is_open()) { std::cerr << "Input file cannot be opened!\n"; exit(1); }
