      Vector v(ft->args_->dim);
      ft->getWordVector(v, ft->dict_->getWord(i));
      v.normalize();
      wordVecs.push_back(v);
    }
    auto queryNN = [&](const Vector& queryIn, const std::unordered_set<std::string>& exclude) {
      Vector query = queryIn;
      query.normalize();
      std::vector<std::pair<real,int32_t>> cand;
      for (int32_t i = 0; i < nw; i++) {
        if (exclude.count(ft->dict_->getWord(i))) continue;
