    } else {
      std::cout << "Loading model " << cargs[0] << "\n" << std::flush;
      std::string a, b, c;
      // Mirror the original loop: it never terminates on EOF and reuses
      // the last triplet (initially empty strings).
      std::string lastA, lastB, lastC;
      while (true) {
        std::cout << "Query triplet (A - B + C)? " << std::flush;
        std::string na, nb, nc;
        bool ok = (bool)(std::cin >> na);
        if (ok) { std::cin >> nb; std::cin >> nc; lastA = na; lastB = nb; lastC = nc; }
        a = lastA; b = lastB; c = lastC;
        Vector va(ft->args_->dim), vb(ft->args_->dim), vc(ft->args_->dim);
        ft->getWordVector(va, a); va.normalize();
        ft->getWordVector(vb, b); vb.normalize();
        ft->getWordVector(vc, c); vc.normalize();
        Vector query(ft->args_->dim); query.zero();
        query.addVector(va, 1); query.addVector(vb, -1); query.addVector(vc, 1);
        std::unordered_set<std::string> excl; excl.insert(a); excl.insert(b); excl.insert(c);
        queryNN(query, excl);
      }
    }
    return 0;
  }

  if (command == "dump") {
    if (cargs.size() < 2) {
      std::cout << "usage: fasttext dump <model> <option>\n\n  <model>      model filename\n  <option>     option from args,dict,input,output\n"; exit(1);
