      std::cout << "ws " << a->ws << "\n";
      std::cout << "epoch " << a->epoch << "\n";
      std::cout << "minCount " << a->minCount << "\n";
      std::cout << "neg " << a->neg << "\n";
      std::cout << "wordNgrams " << a->wordNgrams << "\n";
      std::cout << "loss " << a->lossName() << "\n";
      std::cout << "model " << a->modelName() << "\n";
      std::cout << "bucket " << a->bucket << "\n";
      std::cout << "minn " << a->minn << "\n";
      std::cout << "maxn " << a->maxn << "\n";
      std::cout << "lrUpdateRate " << a->lrUpdateRate << "\n";
      std::cout << "t " << a->t << "\n";
    } else if (option == "dict") {
      std::cout << ft->dict_->size() << "\n";
      for (int32_t i = 0; i < ft->dict_->size(); i++) {
        auto& e = ft->dict_->words_[(size_t)i];
        std::cout << e.word << " " << e.count << " " << (e.type == EntryType::word ? "word" : "label") << "\n";
      }
    } else if (option == "input" || option == "output") {
      if (ft->quant_) {
        std::cerr << "Not supported for quantized models.\n";
        return 0;
      }
      auto mat = option == "input" ? ft->input_ : ft->output_;
      auto dense = std::dynamic_pointer_cast<DenseMatrix>(mat);
      if (!dense) { std::cerr << "Not supported for quantized models.\n"; return 0; }
      std::cout << dense->size(0) << " " << dense->size(1) << "\n";
      for (int64_t i = 0; i < dense->size(0); i++) {
        for (int64_t j = 0; j < dense->size(1); j++) {
          if (j) std::cout << " ";
          std::cout << dense->at(i, j);
        }
        std::cout << "\n";
      }
    } else {
      std::cout << "usage: fasttext dump <model> <option>\n\n  <model>      model filename\n  <option>     option from args,dict,input,output\n"; exit(1);
    }
    return 0;
  }

  std::cerr << MAIN_USAGE;
  exit(1);
}
