// ------------------------------------------------------------- command helpers
static const char* MAIN_USAGE =
    "usage: fasttext <command> <args>\n"
    "\n"
    "The commands supported by fasttext are:\n"
    "\n"
    "  supervised              train a supervised classifier\n"
    "  quantize                quantize a model to reduce the memory usage\n"
    "  test                    evaluate a supervised classifier\n"
    "  test-label              print labels with precision and recall scores\n"
    "  predict                 predict most likely labels\n"
    "  predict-prob            predict most likely labels with probabilities\n"
    "  skipgram                train a skipgram model\n"
    "  cbow                    train a cbow model\n"
    "  print-word-vectors      print word vectors given a trained model\n"
    "  print-sentence-vectors  print sentence vectors given a trained model\n"
    "  print-ngrams            print ngrams given a trained model and word\n"
    "  nn                      query for nearest neighbors\n"
    "  analogies               query for analogies\n"
    "  dump                    dump arguments,dictionary,input/output vectors\n"
    "\n";

static std::shared_ptr<FastText> loadModelOrThrow(const std::string& path) {
  auto ft = std::make_shared<FastText>();
  ft->loadModel(path);
  return ft;
}

static bool streamHasMore(std::istream& in, LineReader& reader) {
  if (reader.pendingEos) return true;
  return in.rdbuf()->sgetc() != std::streambuf::traits_type::eof();
}

// Meter reading for test / test-label.
// Returns false (no examples) if the stream turns out not to be seekable
// when it came from stdin (mirroring the observed pipe behaviour).
static void runTest(std::shared_ptr<FastText> ft, std::istream& in, LineReader& reader,
                    int32_t k, real threshold, Meter& meter, bool fromStdinPipeCheck) {
  if (fromStdinPipeCheck) {
    // std::cin on a pipe reports a position of -1; the original test path
    // then processes no examples. A seekable stdin (regular file) works.
    auto pos = in.rdbuf()->pubseekoff(0, std::ios_base::cur, std::ios_base::in);
    if (pos == (std::streampos)-1) return;
  }
  while (streamHasMore(in, reader)) {
    std::vector<int32_t> line, labels;
    int64_t before = reader.consumed;
    ft->dict_->getLine(reader, line, labels);
    if (reader.consumed == before && !reader.pendingEos && !streamHasMore(in, reader)) break;
    std::vector<std::pair<real,int32_t>> preds;
    // predict even for empty-label lines to mirror internal flow; meter
    // itself ignores examples without gold labels.
    ft->predictOne(line, k, threshold, preds);
    meter.update(labels, preds);
  }
}

struct SimCmp {
  bool operator()(const std::pair<real,int32_t>& a, const std::pair<real,int32_t>& b) const {
    return a.first > b.first; // min-heap by score only
  }
};
static std::vector<std::pair<real,int32_t>> boundedTopK(
    const std::vector<std::pair<real,int32_t>>& candidates, int32_t k) {
  std::priority_queue<std::pair<real,int32_t>, std::vector<std::pair<real,int32_t>>, SimCmp> heap;
  for (auto& c : candidates) {
    heap.push(c);
    if (heap.size() > (size_t)k) heap.pop();
  }
  std::vector<std::pair<real,int32_t>> res;
  while (!heap.empty()) { res.push_back(heap.top()); heap.pop(); }
  std::reverse(res.begin(), res.end());
  return res;
}

} // namespace fasttext

