import math
def loadvec(p):
 d={}
 lines=open(p).read().splitlines()[1:]
 for l in lines:
  p=l.split(); d[p[0]]=[float(x) for x in p[1:] if x]
 return d
for model in ["skipgram","cbow"]:
 for loss in ["softmax","ns","hs","one-vs-all"]:
  a=loadvec(f"refs_train/{model}_{loss}.vec"); b=loadvec(f"my_{model}_{loss}.vec")
  # cosine between vectors per word and vector magnitude diffs
  cos=[]; diff=[]
  for w in a:
   if w in b:
    va,vb=a[w],b[w]
    dot=sum(x*y for x,y in zip(va,vb)); na=math.sqrt(sum(x*x for x in va)); nb=math.sqrt(sum(x*x for x in vb))
    cos.append(dot/(na*nb) if na and nb else 0); diff.append(math.sqrt(sum((x-y)**2 for x,y in zip(va,vb))))
  print(model,loss,"mean_cos",sum(cos)/len(cos),"mean_L2diff",sum(diff)/len(diff),"words",len(cos))
