{"command":"python3 << 'PY'
import math
def sim(reps, lr=0.001):
 # rows input a [1,0], eos[0,1]; output zero 2x2
 inp=[[1.,0.],[0.,1.]]; out=[[0.,0.],[0.,0.]]
 for r in range(reps):
  for target_in, label in [(0,1),(1,0)]:
   hidden=inp[target_in][:]
   scores=[sum(hidden[j]*out[i][j] for j in range(2)) for i in range(2)]
   mx=max(scores); ex=[math.exp(s-mx) for s in scores]; ss=sum(ex); probs=[e/ss for e in ex]
   alphas=[lr*((1 if i==label else 0)-probs[i]) for i in range(2)]
   grad=[sum(alphas[i]*out[i][j] for i in range(2)) for j in range(2)]
   for i in range(2):
    for j in range(2): out[i][j]+=alphas[i]*hidden[j]
   for j in range(2): inp[target_in][j]+=grad[j]  # Variant B coeff 1 (input size1 same A/B)
 return inp,out
for reps in [1,2,5,10,20,50,100,200,500,1000]:
 inp,out=sim(reps); print(reps, inp, out)
PY"}

