          int32_t b = dist(state.rng);
          auto input = dict_->getSubwords(line[(size_t)i]);
          for (int32_t j = i - b; j <= i + b; j++) {
            if (j == i || j < 0 || j >= (int32_t)line.size()) continue;
            modelUpdate(*this, input, line[(size_t)j], lr, state, {});
