import struct, math, subprocess
# Use our myft to get line IDs? Instead compute flat hidden by summing wordvec * subcount for each token incl EOS, divide total subcount
def subcount(w, bin="suporig.bin"):
 return len(subprocess.check_output(["/workspace/executable","print-ngrams",bin,w]).decode().splitlines())
