size,nw,nl=struct.unpack_from('<iii',data,off); off+=12+16
for i in range(size):
 while data[off]!=0: off+=1
 off+=1+9
off+=1; m,n=struct.unpack_from('<qq',data,off); off+=16+m*n*4; off+=1; om,on=struct.unpack_from('<qq',data,off); off+=16
out=[[struct.unpack_from('<f',data,off+(i*on+j)*4)[0] for j in range(on)] for i in range(om)]
print("labels order dict: negative id0, positive id1? entries at nw", nw)
for line in open("test_sup.txt"):
 toks=[t for t in line.split() if not t.startswith("__label__")]
 toks2=toks+["</s>"]
 total=0; hidden=[0]*n
 perword_hidden=[0]*n; 
 for w in toks2:
  c=subcount(w); wv=wordvec(w); total+=c
  for j in range(n): hidden[j]+=wv[j]*c; perword_hidden[j]+=wv[j]
