import struct,math
data=open("qtr_origbase.bin","rb").read(); off=64
size,nw,nl=struct.unpack_from('<iii',data,off); off+=12+16
entries=[]
for i in range(size):
 s=b''
 while data[off]!=0: s+=data[off:off+1]; off+=1
 off+=1+9; entries.append(s.decode())
orig=set(l.split()[0] for l in open("origcutdict.txt").read().splitlines()[1:])
off+=1; m,n=struct.unpack_from('<qq',data,off); off+=16
vals=struct.unpack_from(f'<{m*n}f',data,off)
def norm(i): return math.sqrt(sum(x*x for x in vals[i*n:(i+1)*n]))
allrows=sorted(range(m), key=lambda i:-norm(i)); rank={r:i for i,r in enumerate(allrows)}
ret=[]
for i,w in enumerate(entries[:nw]):
 if w in orig: ret.append((rank[i],w,norm(i)))
ret.sort(reverse=True)
print("lowest retained words by norm rank",ret[:20])
PY"}

