import subprocess, struct
# craftsg.bin is skipgram charmodel with rows [i,1] dim8 bucket200, based on words.txt vocab13
def wordvec(w):
 out=subprocess.check_output(["/workspace/executable","print-word-vectors","craftsg.bin"], input=(w+"\n").encode()).decode().split()
 return float(out[1])
def fnv(s, signed):
 h=2166136261
 for byte in s.encode():
  c = byte if not signed else (byte-256 if byte>=128 else byte)
  h = h ^ (c & 0xffffffff if not signed else (c & 0xffffffff)) # python: for signed, C++ int32 conversion then to uint32 for xor
  # In C++: uint32 h ^= uint32_t(int8_t(byte)); int8_t negative -> int32 -128..-1 -> uint32 0xffffff..
  if signed:
   # recompute properly below
   pass
  h = (h * 16777619) & 0xffffffff
 return h
def fnv_signed(s):
 h=2166136261
 for byte in s.encode():
  sc = byte-256 if byte>=128 else byte
  h = h ^ (sc & 0xffffffff)
  h = (h * 16777619) & 0xffffffff
 return h
def fnv_unsigned(s):
 h=2166136261
 for byte in s.encode():
  h = h ^ byte
  h = (h * 16777619) & 0xffffffff
 return h
def subs(word):
 # generate substrings using unicode chars, as in print-ngrams names from original
 out=subprocess.check_output(["/workspace/executable","print-ngrams","craftsg.bin",word]).decode().splitlines()
 return [l.split()[0] for l in out]
for w in ["café","éx","日本"]:
 ss=subs(w); print(w,"substrings",ss)
 for name,fn in [("unsigned",fnv_unsigned),("signed",fnv_signed)]:
  ids=[13+fn(s)%200 for s in ss]; print(" ",name,"avg id",sum(ids)/len(ids),"ids",ids)
 print(" original avg(first coord)",wordvec(w))
